521	fn render_text(ctx: &Ctx, i: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
522	    out.any_text = true;
523	    let n = &ctx.nodes[i];
524	    let c = &ctx.comp[i];
525	    let style = inline_style(ctx, i, out, true)?;
526	    let mut extra = String::new();
527	    let x = n.x + c.translate.0;
528	    let y = n.y + c.translate.1;
529	    let fam_attr = if let Some(v) = n.inline.iter().find(|d| d.name == "font-family") {
530	        Some(font_family_css(&v.value))
531	    } else {
532	        None
533	    };
534	    let _ = fam_attr;
535	    if !style.is_empty() {
536	        extra = format!(" style=\"{}\"", xml_escape(&style));
537	    }
538	    let lines = &n.lines;
539	    let ls = c.letter_spacing;
540	    let dx_for = |l: &str| -> String {
541	        let cnt = l.chars().count();
542	        if ls != 0.0 && cnt > 1 {
543	            let mut v = vec!["0".to_string()];
544	            for _ in 1..cnt {
545	                v.push(f4(ls));
546	            }
547	            format!(" dx=\"{}\"", v.join(" "))
548	        } else {
549	            String::new()
550	        }
551	    };
552	    if lines.len() <= 1 {
553	        let l = lines.first().cloned().unwrap_or_default();
554	        s.push_str(&format!(
555	            "{}<text class=\"lini-text\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
556	            ind(ind_n),
557	            f4(x),
558	            f4(y),
559	            dx_for(&l),
560	            extra,
561	            xml_escape(&l)
562	        ));
563	    } else {
564	        let pitch = 1.2 * c.font_size + c.line_spacing;
565	        let total = (lines.len() as f64 - 1.0) * pitch;
566	        let first = y - total / 2.0 + 0.358 * c.font_size;
567	        let mut t = String::new();
568	        for (k, l) in lines.iter().enumerate() {
569	            if k == 0 {
570	                t.push_str(&format!("<tspan x=\"{}\" y=\"{}\"{}>{}</tspan>", f4(x), f4(first), dx_for(l), xml_escape(l)));
571	            } else {
572	                t.push_str(&format!("<tspan x=\"{}\" dy=\"{}\"{}>{}</tspan>", f4(x), f4(pitch), dx_for(l), xml_escape(l)));
573	            }
574	        }
575	        s.push_str(&format!("{}<text class=\"lini-text\" x=\"{}\" y=\"{}\"{}>{}</text>\n", ind(ind_n), f4(x), f4(y), extra, t));
576	    }
577	    Ok(())
578	}
