use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
    pub watch: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: failed to read stdin: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => String::from_utf8(b).map_err(|_| format!("error: {}: stream did not contain valid UTF-8", path)),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet, src);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    b.resolve_links().map_err(|e| (e, vec![]))?;
    b.unworn_class_warnings();
    let nodes = std::mem::take(&mut b.nodes);
    let links = std::mem::take(&mut b.links);
    let mut warnings = std::mem::take(&mut b.warnings);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links,
        warnings: std::mem::take(&mut warnings),
        root_font_size: 15.0,
    };
    compile::compute(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    layout::measure(&mut ctx, 0, None);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn write_out(opts: &Options, text: &str) {
    match &opts.output {
        Some(path) if path != "-" => {
            let _ = std::fs::write(path, text.as_bytes());
        }
        _ => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
        }
    }
}

fn html_wrap(svg: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <title>lini</title>\n</head>\n<body>\n{}</body>\n</html>\n",
        svg
    )
}

fn run_compile(input: &str, opts: &Options) -> i32 {
    if opts.format != "svg" && opts.format != "html" {
        eprintln!("error: invalid --format '{}' (expected svg|html)", opts.format);
        return 3;
    }
    if let Some(t) = &opts.theme {
        if theme::resolve(t).is_none() {
            eprintln!(
                "error: theme '{}': not a built-in (try: default, light, dark, high-contrast, blueprint), and reading it as a file failed: No such file or directory (os error 2)",
                t
            );
            return 2;
        }
    }
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let result = compile_src(&src, &file, opts);
    if opts.json {
        let (diags, failed) = match &result {
            Ok((_, w)) => (w.clone(), false),
            Err((e, w)) => {
                let mut d = w.clone();
                d.push(e.clone());
                (d, true)
            }
        };
        print!("{}", diag::render_json(&file, &src, &diags));
        if failed || (opts.strict && !diags.is_empty()) {
            return 1;
        }
        return 0;
    }
    match result {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            if !opts.check {
                let text = if opts.format == "html" { html_wrap(&svg) } else { svg };
                write_out(opts, &text);
            }
            if opts.strict && !warns.is_empty() {
                return 1;
            }
            0
        }
        Err((e, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            1
        }
    }
}

fn run_fmt(input: &str, check: bool, stdout: bool) -> i32 {
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let out = match format::format(&src) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("{}", diag::render_text(&file, &src, &e));
            return 1;
        }
    };
    if check {
        if out != src {
            eprintln!("{}: would reformat", file);
            return 1;
        }
        return 0;
    }
    if stdout || input == "-" {
        print!("{}", out);
        return 0;
    }
    if out != src {
        let _ = std::fs::write(input, out.as_bytes());
    }
    0
}

fn run_theme(name: &Option<String>) -> i32 {
    match name {
        None => {
            print!("{}", theme::LIST);
            0
        }
        Some(n) => match theme::css_of(n) {
            Some(css) => {
                print!("{}", css);
                0
            }
            None => {
                eprintln!("error: unknown theme '{}' (try one of: default, light, dark, high-contrast, blueprint)", n);
                3
            }
        },
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let code = match cli::parse(&args) {
        cli::Outcome::Print(s) => {
            print!("{}", s);
            0
        }
        cli::Outcome::Fail(s) => {
            eprint!("{}", s);
            3
        }
        cli::Outcome::Run(p) => match &p.cmd {
            cli::Cmd::Compile { input } => run_compile(input, &p.opts),
            cli::Cmd::Theme { name } => run_theme(name),
            cli::Cmd::Highlight { input: _, css: true } => {
                print!("{}", cli::HIGHLIGHT_CSS);
                0
            }
            cli::Cmd::Highlight { input: Some(input), css: false } => match read_input(input) {
                Ok(src) => {
                    print!("{}", highlight::highlight(&src));
                    0
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            cli::Cmd::Fmt { input, check, stdout } => run_fmt(input, *check, *stdout),
            cli::Cmd::Desugar { input } => match read_input(input) {
                Ok(src) => {
                    let file = if input == "-" { "<stdin>".to_string() } else { input.clone() };
                    match desugar::desugar(&src) {
                        Ok(out) => {
                            print!("{}", out);
                            0
                        }
                        Err(e) => {
                            eprintln!("{}", diag::render_text(&file, &src, &e));
                            1
                        }
                    }
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            _ => 0,
        },
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}
// Layout: sizes and centre positions for the node tree.

use crate::compile::{Align, Ctx, Dir};
use crate::font;
use crate::types::Prim;

pub fn outer(ctx: &Ctx, i: usize) -> (f64, f64) {
    let n = &ctx.nodes[i];
    let c = &ctx.comp[i];
    if n.prim == Prim::Text {
        return (n.w, n.h);
    }
    let s = if c.has_stroke { c.stroke_width } else { 0.0 };
    (n.w + s, n.h + s)
}

pub fn transform_text(s: &str, tt: &Option<String>) -> String {
    match tt.as_deref() {
        Some("uppercase") => s.to_uppercase(),
        Some("lowercase") => s.to_lowercase(),
        Some("capitalize") => {
            let mut out = String::new();
            let mut start = true;
            for ch in s.chars() {
                if start && ch.is_alphabetic() {
                    out.extend(ch.to_uppercase());
                    start = false;
                } else {
                    out.push(ch);
                    if ch.is_whitespace() {
                        start = true;
                    } else {
                        start = false;
                    }
                }
            }
            out
        }
        _ => s.to_string(),
    }
}

pub fn line_width(ctx: &Ctx, i: usize, s: &str) -> f64 {
    let c = &ctx.comp[i];
    let w = font::text_width(c.family, c.font_weight, c.font_size, s);
    let n = s.chars().count();
    if n > 1 {
        w + c.letter_spacing * (n as f64 - 1.0)
    } else {
        w
    }
}

// Greedy word wrap at the given width.
pub fn wrap(ctx: &Ctx, i: usize, text: &str, maxw: f64) -> Vec<String> {
    let mut out = Vec::new();
    for para in text.split('\n') {
        let words: Vec<&str> = para.split(' ').filter(|w| !w.is_empty()).collect();
        if words.is_empty() {
            out.push(String::new());
            continue;
        }
        let mut cur = String::new();
        for w in words {
            if cur.is_empty() {
                cur = w.to_string();
                continue;
            }
            let cand = format!("{} {}", cur, w);
            if line_width(ctx, i, &cand) > maxw {
                out.push(cur);
                cur = w.to_string();
            } else {
                cur = cand;
            }
        }
        out.push(cur);
    }
    out
}

pub fn text_block_height(ctx: &Ctx, i: usize, nlines: usize) -> f64 {
    let c = &ctx.comp[i];
    if nlines <= 1 {
        c.font_size
    } else {
        nlines as f64 * 1.2 * c.font_size + (nlines as f64 - 1.0) * c.line_spacing
    }
}

pub fn measure_text(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
    let raw = ctx.nodes[i].text.clone().unwrap_or_default();
    let tt = ctx.comp[i].text_transform.clone();
    let text = transform_text(raw.trim(), &tt);
    let lines: Vec<String> = match avail {
        Some(m) if !ctx.comp[i].nowrap => wrap(ctx, i, &text, m),
        _ => text.split('\n').map(|s| s.to_string()).collect(),
    };
    let mut w: f64 = 0.0;
    for l in &lines {
        w = w.max(line_width(ctx, i, l));
    }
    let h = text_block_height(ctx, i, lines.len());
    let n = &mut ctx.nodes[i];
    n.lines = lines;
    n.w = w;
    n.h = h;
}

pub fn measure(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
    let prim = ctx.nodes[i].prim;
    match prim {
        Prim::Text => measure_text(ctx, i, avail),
        Prim::Line | Prim::Poly | Prim::Path => measure_geo(ctx, i),
        _ => {
            if crate::chart::is_chart(ctx, i) {
                crate::chart::measure(ctx, i)
            } else if ctx.comp[i].layout == "grid" {
                measure_grid(ctx, i, avail)
            } else {
                measure_flow(ctx, i, avail)
            }
        }
    }
}

#[derive(Clone, Debug)]
pub enum Track {
    Auto,
    Fixed(f64),
}

pub fn parse_tracks(ctx: &Ctx, v: &crate::ast::Value) -> Vec<Track> {
    use crate::ast::{Expr, Term};
    let env = &ctx.sheet.env;
    let mut out = Vec::new();
    for g in &v.groups {
        for t in g {
            match t {
                Term::Ident(s, _) if s == "auto" => out.push(Track::Auto),
                Term::Call(name, args, _) if name == "repeat" => {
                    let n = args.first().and_then(|a| env.eval(a, &Default::default()).ok()).and_then(|x| x.num()).unwrap_or(1.0) as usize;
                    let tr = match args.get(1) {
                        Some(Expr::Ident(s, _)) if s == "auto" => Track::Auto,
                        Some(a) => match env.eval(a, &Default::default()).ok().and_then(|x| x.num()) {
                            Some(x) => Track::Fixed(x),
                            None => Track::Auto,
                        },
                        None => Track::Auto,
                    };

                    };
                    for _ in 0..n {
                        out.push(tr.clone());
                    }
                }
                _ => {
                    if let Some(x) = crate::style::term_num(env, t) {
                        out.push(Track::Fixed(x));
                    }
                }
            }
        }
    }
    out
}

pub fn measure_grid(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
    let c = ctx.comp[i].clone();
    let pad = c.padding;
    let _ = avail;
    let props = ctx.nodes[i].props.clone();
    let cols = props.get("columns").map(|v| parse_tracks(ctx, v)).unwrap_or_else(|| vec![Track::Auto]);
    let row_specs = props.get("rows").map(|v| parse_tracks(ctx, v)).unwrap_or_default();
    let ncols = cols.len().max(1);
    let children = ctx.nodes[i].children.clone();
    let mut flow = Vec::new();
    let mut pinned = Vec::new();
    for &ch in &children {
        if ctx.comp[ch].pin.is_some() {
            pinned.push(ch);
        } else {
            flow.push(ch);
        }
    }
    for &ch in &children {
        measure(ctx, ch, None);
    }
    // placement: (col, row, colspan, rowspan)
    let env = ctx.sheet.env.clone();
    let mut occupied: Vec<Vec<bool>> = Vec::new();
    let mut place: Vec<(usize, usize, usize, usize)> = Vec::new();
    let mut cur_r = 0usize;
    let mut cur_c = 0usize;
    let ensure = |occ: &mut Vec<Vec<bool>>, r: usize| {
        while occ.len() <= r {
            occ.push(vec![false; ncols]);
        }
    };
    for &ch in &flow {
        let p = &ctx.nodes[ch].props;
        let span: Vec<f64> = p.get("span").map(|v| crate::style::value_nums(&env, v)).unwrap_or_default();
        let cs = span.first().map(|x| *x as usize).unwrap_or(1).max(1).min(ncols);
        let rs = span.get(1).map(|x| *x as usize).unwrap_or(1).max(1);
        if let Some(cell) = p.get("cell").map(|v| crate::style::value_nums(&env, v)) {
            if cell.len() >= 2 {
                let cc = (cell[0] as usize).max(1) - 1;
                let rr = (cell[1] as usize).max(1) - 1;
                ensure(&mut occupied, rr + rs - 1);
                for r in rr..rr + rs {
                    for k in cc..(cc + cs).min(ncols) {
                        occupied[r][k] = true;
                    }
                }
                place.push((cc, rr, cs, rs));
                continue;
            }
        }
        loop {
            ensure(&mut occupied, cur_r + rs - 1);
            if cur_c + cs > ncols {
                cur_c = 0;
                cur_r += 1;
                continue;
            }
            let mut free = true;
            for r in cur_r..cur_r + rs {
                ensure(&mut occupied, r);
                for k in cur_c..cur_c + cs {
                    if occupied[r][k] {
                        free = false;
                    }
                }
            }
            if free {
                break;
            }
            cur_c += 1;
        }
        for r in cur_r..cur_r + rs {
            for k in cur_c..cur_c + cs {
                occupied[r][k] = true;
            }
        }
        place.push((cur_c, cur_r, cs, rs));
        cur_c += cs;
    }
    let nrows = occupied.len();
    let (gr, gc) = c.gap;
    let mut colw: Vec<f64> = vec![0.0; ncols];
    let mut rowh: Vec<f64> = vec![0.0; nrows];
    let col_fixed: Vec<Option<f64>> = (0..ncols).map(|k| match cols.get(k) { Some(Track::Fixed(x)) => Some(*x), _ => None }).collect();
    let row_fixed: Vec<Option<f64>> = (0..nrows).map(|k| match row_specs.get(k) { Some(Track::Fixed(x)) => Some(*x), _ => None }).collect();
    for k in 0..ncols {
        if let Some(x) = col_fixed[k] {
            colw[k] = x;
        }
    }
    for k in 0..nrows {
        if let Some(x) = row_fixed[k] {
            rowh[k] = x;
        }
    }
    let sizes: Vec<(f64, f64)> = flow.iter().map(|&ch| outer(ctx, ch)).collect();
    for (idx, &(cc, rr, cs, rs)) in place.iter().enumerate() {
        let (w, h) = sizes[idx];
        if cs == 1 && col_fixed[cc].is_none() {
            colw[cc] = colw[cc].max(w);
        }
        if rs == 1 && row_fixed[rr].is_none() {
            rowh[rr] = rowh[rr].max(h);
        }
    }
    for (idx, &(cc, rr, cs, rs)) in place.iter().enumerate() {
        let (w, h) = sizes[idx];
        if cs > 1 {
            let cur: f64 = colw[cc..cc + cs].iter().sum::<f64>() + gc * (cs as f64 - 1.0);
            if w > cur {
                let autos: Vec<usize> = (cc..cc + cs).filter(|k| col_fixed[*k].is_none()).collect();
                if !autos.is_empty() {
                    let extra = (w - cur) / autos.len() as f64;
                    for k in autos {
                        colw[k] += extra;
                    }
                }
            }
        }
        if rs > 1 {
            let cur: f64 = rowh[rr..rr + rs].iter().sum::<f64>() + gr * (rs as f64 - 1.0);
            if h > cur {
                let autos: Vec<usize> = (rr..rr + rs).filter(|k| row_fixed[*k].is_none()).collect();
                if !autos.is_empty() {
                    let extra = (h - cur) / autos.len() as f64;
                    for k in autos {
                        rowh[k] += extra;
                    }
                }
            }
        }
    }
    let cw: f64 = colw.iter().sum::<f64>() + gc * (ncols as f64 - 1.0).max(0.0);
    let chh: f64 = rowh.iter().sum::<f64>() + gr * (nrows as f64 - 1.0).max(0.0);
    let mut w = cw + pad[1] + pad[3];
    let mut h = chh + pad[0] + pad[2];
    if let Some(fw) = c.width {
        w = w.max(fw);
    }
    if let Some(fh) = c.height {
        h = h.max(fh);
    }
    ctx.nodes[i].w = w;
    ctx.nodes[i].h = h;
    let x0 = -w / 2.0 + pad[3] + (w - pad[1] - pad[3] - cw) / 2.0;
    let y0 = -h / 2.0 + pad[0] + (h - pad[0] - pad[2] - chh) / 2.0;
    let mut colx = vec![0.0; ncols];
    let mut acc = x0;
    for k in 0..ncols {
        colx[k] = acc;
        acc += colw[k] + gc;
    }
    let mut rowy = vec![0.0; nrows];
    let mut acc = y0;
    for k in 0..nrows {
        rowy[k] = acc;
        acc += rowh[k] + gr;
    }
    if ctx.nodes[i].props.contains_key("gap-fill") {
        let mut g = Vec::new();
        if gc > 0.0 {
            for k in 0..ncols.saturating_sub(1) {
                g.push((colx[k] + colw[k], -h / 2.0, gc, h));
            }
        }
        if gr > 0.0 {
            for k in 0..nrows.saturating_sub(1) {
                g.push((-w / 2.0, rowy[k] + rowh[k], w, gr));
            }
        }
        ctx.nodes[i].gutters = g;
    }
    for (idx, &ch) in flow.iter().enumerate() {
        let (cc, rr, cs, rs) = place[idx];
        let (ow, oh) = sizes[idx];
        let cx0 = colx[cc];
        let cwid: f64 = colw[cc..cc + cs].iter().sum::<f64>() + gc * (cs as f64 - 1.0);
        let ry0 = rowy[rr];
        let rhei: f64 = rowh[rr..(rr + rs).min(nrows)].iter().sum::<f64>() + gr * (rs as f64 - 1.0);
        let x = match c.align {
            Align::Start => cx0 + ow / 2.0,
            Align::End => cx0 + cwid - ow / 2.0,
            _ => cx0 + cwid / 2.0,
        };
        let y = match c.justify {
            Align::Start => ry0 + oh / 2.0,
            Align::End => ry0 + rhei - oh / 2.0,
            _ => ry0 + rhei / 2.0,
        };
        ctx.nodes[ch].x = x;
        ctx.nodes[ch].y = y;
    }
    for &p in &pinned {
        place_pinned(ctx, i, p);
    }
}

pub fn measure_flow(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
    let c = ctx.comp[i].clone();
    let pad = c.padding;
    let mut inner_avail = avail.map(|a| a - pad[1] - pad[3]);
    if let Some(m) = c.max_width {
        let a = m - pad[1] - pad[3];
        inner_avail = Some(inner_avail.map_or(a, |x: f64| x.min(a)));
    }
    let children = ctx.nodes[i].children.clone();
    let mut flow = Vec::new();
    let mut pinned = Vec::new();
    for &ch in &children {
        if ctx.comp[ch].pin.is_some() {
            pinned.push(ch);
        } else {
            flow.push(ch);
        }
    }
    for &ch in &children {
        measure(ctx, ch, if ctx.comp[ch].pin.is_some() { None } else { inner_avail });
    }
    let sizes: Vec<(f64, f64)> = flow.iter().map(|&ch| outer(ctx, ch)).collect();
    let (gap_main, row) = match c.direction {
        Dir::Row => (c.gap.1, true),
        Dir::Column => (c.gap.0, false),
    };
    let n = sizes.len();
    let mut main: f64 = 0.0;
    let mut cross: f64 = 0.0;
    for &(w, h) in &sizes {
        if row {
            main += w;
            cross = cross.max(h);
        } else {
            main += h;
            cross = cross.max(w);
        }
    }
    if n > 1 {
        main += gap_main * (n as f64 - 1.0);
    }
    let (cw, ch) = if row { (main, cross) } else { (cross, main) };
    let mut w = cw + pad[1] + pad[3];
    let mut h = ch + pad[0] + pad[2];
    if let Some(fw) = c.width {
        w = w.max(fw);
    }
    if let Some(fh) = c.height {
        h = h.max(fh);
    }
    ctx.nodes[i].w = w;
    ctx.nodes[i].h = h;
    // place flow children
    let inner_l = -w / 2.0 + pad[3];
    let inner_t = -h / 2.0 + pad[0];
    let inner_w = w - pad[1] - pad[3];
    let inner_h = h - pad[0] - pad[2];
    let free = if row { inner_w - main } else { inner_h - main };
    let start = match c.justify {
        Align::Start | Align::Stretch => 0.0,
        Align::Center => free / 2.0,
        Align::End => free,
    };
    let mut cursor = start;
    for (k, &chi) in flow.iter().enumerate() {
        let (ow, oh) = sizes[k];
        if row {
            let x = inner_l + cursor + ow / 2.0;
            let y = match c.align {
                Align::Start => inner_t + oh / 2.0,
                Align::End => inner_t + inner_h - oh / 2.0,
                _ => inner_t + inner_h / 2.0,
            };
            ctx.nodes[chi].x = x;
            ctx.nodes[chi].y = y;
            cursor += ow + gap_main;
        } else {
            let y = inner_t + cursor + oh / 2.0;
            let x = match c.align {
                Align::Start => inner_l + ow / 2.0,
                Align::End => inner_l + inner_w - ow / 2.0,
                _ => inner_l + inner_w / 2.0,
            };
            ctx.nodes[chi].x = x;
            ctx.nodes[chi].y = y;
            cursor += oh + gap_main;
        }
    }
    if ctx.nodes[i].props.contains_key("gap-fill") && n > 1 && gap_main > 0.0 {
        let mut g = Vec::new();
        let mut cur = start;
        for k in 0..n - 1 {
            let (ow, oh) = sizes[k];
            cur += if row { ow } else { oh };
            if row {
                g.push((inner_l + cur, -h / 2.0, gap_main, h));
            } else {
                g.push((-w / 2.0, inner_t + cur, w, gap_main));
            }
            cur += gap_main;
        }
        ctx.nodes[i].gutters = g;
    }
    if ctx.nodes[i].prim == Prim::Cyl {
        let (_, oh) = outer(ctx, i);
        let dy = 0.03 * oh;
        for &chi in &flow {
            ctx.nodes[chi].y += dy;
        }
    }
    for &p in &pinned {
        place_pinned(ctx, i, p);
    }
}

pub fn place_pinned(ctx: &mut Ctx, parent: usize, i: usize) {
    let pin = ctx.comp[i].pin.clone().unwrap_or_default();
    let pw = ctx.nodes[parent].w;
    let ph = ctx.nodes[parent].h;
    let (cw, chh) = outer(ctx, i);
    let words: Vec<&str> = pin.split_whitespace().collect();
    let mut x = 0.0;
    let mut y = 0.0;
    for w in &words {
        match *w {
            "top" => y = -ph / 2.0 + chh / 2.0,
            "bottom" => y = ph / 2.0 - chh / 2.0,
            "left" => x = -pw / 2.0 + cw / 2.0,
            "right" => x = pw / 2.0 - cw / 2.0,
            _ => {}
        }
    }
    ctx.nodes[i].x = x;
    ctx.nodes[i].y = y;
}

pub fn eval_points(ctx: &Ctx, i: usize) -> Vec<(f64, f64)> {
    use crate::ast::Term;
    use crate::eval::EV;
    let env = &ctx.sheet.env;
    let v = match ctx.nodes[i].props.get("points") {
        Some(v) => v.clone(),
        None => return vec![],
    };
    let samples = ctx.nodes[i].props.get("samples").and_then(|s| crate::style::value_num(env, s)).unwrap_or(2.0).max(2.0) as usize;
    let mut pts = Vec::new();
    for g in &v.groups {
        let nums: Vec<f64> = g.iter().filter_map(|t| crate::style::term_num(env, t)).collect();
        if g.len() == 2 && nums.len() == 2 {
            pts.push((nums[0], nums[1]));
            continue;
        }
        if g.len() == 1 {
            // a parametric point: sample u over [0, 1]
            let t = &g[0];
            for k in 0..samples {
                let u = k as f64 / (samples as f64 - 1.0);
                let mut locals = std::collections::HashMap::new();
                locals.insert("u".to_string(), EV::Num(u));
                let r = match t {
                    Term::Group(e, _) => env.eval(e, &locals),
                    Term::Call(..) => env.eval_term(t, &locals),
                    _ => continue,
                };
                if let Ok(EV::Tuple(xs)) = r {
                    if xs.len() >= 2 {
                        pts.push((xs[0].num().unwrap_or(0.0), xs[1].num().unwrap_or(0.0)));
                    }
                }
            }
        }
    }
    pts
}

pub fn measure_geo(ctx: &mut Ctx, i: usize) {
    use crate::geom::{path_bbox, BBox};
    use crate::scene::Geo;
    let prim = ctx.nodes[i].prim;
    let mut bb = BBox::empty();
    let geo = if prim == Prim::Path {
        let d = match ctx.nodes[i].props.get("path").and_then(crate::style::single_term) {
            Some(crate::ast::Term::Str(s, _)) => s.clone(),
            _ => String::new(),
        };
        bb = path_bbox(&d);
        Geo::Path(d)
    } else {
        let pts = eval_points(ctx, i);
        for &(x, y) in &pts {
            bb.add(x, y);
        }
        Geo::Points(pts)
    };
    let n = &mut ctx.nodes[i];
    n.w = bb.w();
    n.h = bb.h();
    n.geo_off = (-bb.cx(), -bb.cy());
    n.geo = Some(geo);
}

