#!/usr/bin/env python3
# usage: d.py [-n N] [-x] files...   diff original vs ours, ignoring scope hash lines if -x
import subprocess,sys,os,re,difflib
MINE='/tmp/bin-link/executable'
ORIG='/workspace/executable'
args=sys.argv[1:]
n=40; strip=False; extra=[]
files=[]
i=0
while i<len(args):
    a=args[i]
    if a=='-n': n=int(args[i+1]); i+=2; continue
    if a=='-x': strip=True; i+=1; continue
    if a=='-a': extra=args[i+1].split(); i+=2; continue
    files.append(a); i+=1
def run(b,f):
    d=os.path.dirname(os.path.abspath(f)); bn=os.path.basename(f)
    r=subprocess.run([b]+extra+[bn],capture_output=True,cwd=d)
    o=r.stdout.decode(errors='replace'); e=r.stderr.decode(errors='replace')
    if strip:
        o=re.sub(r'lini-scope-[0-9a-f]{8}','lini-scope-X',o)
    return o,e,r.returncode
for f in files:
    o1,e1,c1=run(ORIG,f); o2,e2,c2=run(MINE,f)
    print('=====',f,'exit',c1,c2, 'SAME' if (o1,e1,c1)==(o2,e2,c2) else '')
    if e1!=e2:
        for l in list(difflib.unified_diff(e1.splitlines(),e2.splitlines(),'orig','mine',lineterm='',n=0))[:n]: print(l)
    if o1!=o2:
        for l in list(difflib.unified_diff(o1.splitlines(),o2.splitlines(),'orig','mine',lineterm='',n=0))[:n]: print(l)

