src=sys.argv[1]
full='-f' in sys.argv
scene='-s' in sys.argv
bin_='/workspace/executable'
if '-m' in sys.argv: bin_='/tmp/bin-link/executable'
d=tempfile.mkdtemp(prefix='/tmp/link/rr.')
open(d+'/r_in.lini','w').write(src)
r=subprocess.run([bin_,'r_in.lini'],capture_output=True,cwd=d)
o=r.stdout.decode(); e=r.stderr.decode()
if e: print(e,end='')
if full: print(o); sys.exit()
lines=o.split('\n')
if lines and lines[0].startswith('<svg'):
    m=re.search(r'viewBox="([^"]*)"',lines[0]); print('viewBox',m.group(1) if m else '')
