input.content:
import subprocess,sys,os,re,tempfile
lefts=["", "<", "*", ">", ">o", ">+", "+", "+o"]
lines=["-", "--", "---", "~"]
rights=["", ">", "*", "<", "+", "+<", "o<", "o+"]
sel=sys.argv[1:]
def run(src):
    d=tempfile.mkdtemp(prefix='/tmp/link/rr.')
    open(d+'/r_in.lini','w').write(src)
    r=subprocess.run(['/workspace/executable','r_in.lini'],capture_output=True,cwd=d)
    return r.stdout.decode(), r.stderr.decode()
ops=[]
if sel: ops=sel
else:
    for l in lefts:
        for r in rights:
            ops.append(l+'-'+r)
for op in ops:
    o,e=run('a %s b'%op)
    print('=== op',op)
    if e: print(e.strip())
    inl=False
    for l in o.split('\n'):
        if 'lini-links' in l: inl=True
        if inl and ('<path' in l or 'marker' in l or 'lini-link"' in l): print('   ',l.strip())
        if not inl and ('.lini-link' in l or ('lini-marker' in l)): print('   ',l.strip())

