    if d1 == (d0 + 1) % 4 {
        1
    } else if d0 == (d1 + 1) % 4 {
        -1
    } else {
        0
    }
}

// Extra cost of a detour segment: it is priced at the middle of its channel
// (an open side counts K + 20 deep), not at the hugging position.
fn detour_penalty(env: &Env, pts: &[(f64, f64)]) -> f64 {
    let k = env.k;
    let solids = env.solids();
    let mut pen = 0.0;
    let n = pts.len();
    if n < 4 {
        return 0.0;
    }
    for i in 1..n - 2 {
        let d0 = seg_dir(pts[i - 1], pts[i]);
        let d1 = seg_dir(pts[i], pts[i + 1]);
        let d2 = seg_dir(pts[i + 1], pts[i + 2]);
        if d0 != (d2 + 2) % 4 {
            continue;
        }
        // U-turn segment: the legs point along d0 (into the channel)
        let p = pts[i];
        let q = pts[i + 1];
        let _ = d1;
        let horizontal = (p.1 - q.1).abs() < 1e-9;
        // distance to the nearest obstacle beyond the segment (in direction d0)
        let (lo, hi) = if horizontal { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
        let pos = if horizontal { p.1 } else { p.0 };
        let mut far = f64::INFINITY;
        for r in &solids {
            let (rlo, rhi, near) = if horizontal {
                (r.x0, r.x1, if d0 == 1 { r.y0 - pos } else { pos - r.y1 })
            } else {
                (r.y0, r.y1, if d0 == 0 { r.x0 - pos } else { pos - r.x1 })
            };
            if rlo < hi - EPS && rhi > lo + EPS && near >= -EPS {
                far = far.min(near);
            }
        }
        let depth = far.min(k + 20.0);
        pen += depth; // two legs, each half the depth longer
    }
    pen
}

fn route_one(ctx: &Ctx, world: &World, req: &LinkReq) -> Option<Path> {
    let env = Env { k: req.k, obs: crate::links::obstacles(ctx, world, req.from, req.to), a: world.rects[req.from], b: world.rects[req.to] };
    let sas: Vec<Side> = match req.anchor_a {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let sbs: Vec<Side> = match req.anchor_b {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let mut best: Option<(f64, Path)> = None;
    for &sa in &sas {
        for &sb in &sbs {
            let pr = PortReq { sides_a: &[sa], sides_b: &[sb] };
            if let Some(mut p) = search(&env, &pr) {
                let c = p.cost + detour_penalty(&env, &p.pts);
                if best.as_ref().map_or(true, |(bc, _)| c < *bc - 1e-9) {
                    centre_staircases(&env, &mut p.pts);
                    best = Some((c, p));
                }
            }
        }
    }
    let (_, mut p) = best?;
    collapse_z(&env, &mut p);
    Some(p)
}

// A two-bend route between facing sides becomes straight when the sides'
// port ranges overlap: the wire runs mid-overlap.
fn collapse_z(env: &Env, p: &mut Path) {
    if p.pts.len() != 4 {
        return;
    }
    let k = env.k;
    let opposite = (p.sa.idx() + 2) % 4 == p.sb.idx();
    if !opposite {
        return;
    }
    let (a0, a1) = side_span(&env.a, p.sa);
    let (b0, b1) = side_span(&env.b, p.sb);
    let lo = (a0 + k).max(b0 + k);
    let hi = (a1 - k).min(b1 - k);
    if lo > hi + 1e-9 {
        return;
    }
    let m = (lo + hi) / 2.0;
    let s = p.pts[0];
    let e = p.pts[3];
    if p.sa.horizontal() {
        p.pts = vec![(m, s.1), (m, e.1)];
    } else {
        p.pts = vec![(s.0, m), (e.0, m)];
    }
}

// Corner radii: terminal segments can be used whole (after the marker
// pull-back), interior ones are shared half and half.
pub fn corner_radii(pts: &[(f64, f64)], r: f64, pull_s: f64, pull_e: f64) -> Vec<f64> {
    let n = pts.len();
    if n < 3 {
        return vec![];
    }
    let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
    let mut out = Vec::new();
    for c in 1..n - 1 {
        let before = if c == 1 { seg(0) - pull_s } else { seg(c - 1) / 2.0 };
        let after = if c == n - 2 { seg(c) - pull_e } else { seg(c) / 2.0 };
        out.push(r.min(before).min(after).max(0.0));
    }
    out
}

pub fn route_links(ctx: &Ctx, world: &World, reqs: &[LinkReq]) -> Vec<Routed> {
    let mut out = Vec::new();
    for req in reqs {
        let a = world.rects[req.from];
        let b = world.rects[req.to];
        if req.routing == "straight" {
            let (p, q) = crate::links::stray_line(&a, &b);
            out.push(Routed { stray: false, pts: vec![p, q], radii: vec![], curve: None, sa: None, sb: None });
            continue;
        }
        match route_one(ctx, world, req) {
            Some(p) => {
                if req.routing == "natural" {
                    let (pts, curve) = natural(&p, req);
                    out.push(Routed { stray: false, pts, radii: vec![], curve: Some(curve), sa: Some(p.sa), sb: Some(p.sb) });
                    continue;
                }
                let radii = corner_radii(&p.pts, req.radius, req.pull_s, req.pull_e);
                out.push(Routed { stray: false, pts: p.pts, radii, curve: None, sa: Some(p.sa), sb: Some(p.sb) });
            }
            None => out.push(Routed { stray: true, pts: vec![], radii: vec![], curve: None, sa: None, sb: None }),
        }
    }
    out
}

// Natural routing: an S-curve between the two port stubs.
fn natural(p: &Path, req: &LinkReq) -> (Vec<(f64, f64)>, [(f64, f64); 4]) {
    let s = p.pts[0];
    let e = *p.pts.last().unwrap();
    let ds = p.sa.dir();
    let de = p.sb.dir();
    let stub = 2.0;
    let s1 = (s.0 + ds.0 * stub, s.1 + ds.1 * stub);
    let e_stub = stub + if req.pull_e > 0.0 { req.pull_e + 0.5 + 2.0 } else { 0.0 };
    let _ = e_stub;
    let e1 = (e.0 + de.0 * stub, e.1 + de.1 * stub);
    let h = if p.sa.horizontal() { (e1.1 - s1.1).abs() } else { (e1.0 - s1.0).abs() };
    let c1 = (s1.0 + ds.0 * h, s1.1 + ds.1 * h);
    let c2 = (e1.0 + de.0 * h, e1.1 + de.1 * h);
    (vec![s, e], [s1, c1, c2, e1])
}
