// Wire planning on top of the single-route search: links between the same
// two nodes travel as a bundle (one route, spread ports, stacked tracks),
// then corners get their radii.

use crate::compile::Ctx;
use crate::links::{Routed, World};
use crate::route::*;

#[derive(Clone, Debug)]
pub struct LinkReq {
    pub from: usize,
    pub to: usize,
    pub anchor_a: Option<Side>,
    pub anchor_b: Option<Side>,
    pub k: f64,
    pub radius: f64,
    pub routing: String,
    pub stmt: usize,
    // marker pull-back from the boundary point (0: none)
    pub pull_s: f64,
    pub pull_e: f64,
    // marker glyph length at each end (0: no marker)
    pub mark_len_s: f64,
    pub mark_len_e: f64,
}

// Side enumeration order: east, south, west, north.
pub const ORDER: [Side; 4] = [Side::Right, Side::Bottom, Side::Left, Side::Top];

// Clockwise tangent of a side.
pub fn tangent(s: Side) -> (f64, f64) {
    match s {
        Side::Top => (1.0, 0.0),
        Side::Right => (0.0, 1.0),
        Side::Bottom => (-1.0, 0.0),
        Side::Left => (0.0, -1.0),
    }
}

fn side_len(r: &Rect, s: Side) -> f64 {
    let (a, b) = side_span(r, s);
    b - a
}

fn dvec(d: usize) -> (f64, f64) {
    match d {
        0 => (1.0, 0.0),
        1 => (0.0, 1.0),
        2 => (-1.0, 0.0),
        _ => (0.0, -1.0),
    }
}

struct Bundle {
    reqs: Vec<usize>,
    p: usize,
    q: usize,
    anchor_p: Option<Side>,
    anchor_q: Option<Side>,
}

fn bundles_of(reqs: &[LinkReq]) -> (Vec<Bundle>, Vec<usize>) {
    let mut out: Vec<Bundle> = Vec::new();
    let mut of = vec![usize::MAX; reqs.len()];
    for (i, r) in reqs.iter().enumerate() {
        if r.routing != "orthogonal" || r.from == r.to {
            continue;
        }
        let found = out.iter().position(|b| {
            let first = &reqs[b.reqs[0]];
            if first.k != r.k {
                return false;
            }
            if r.from == b.p && r.to == b.q {
                r.anchor_a == b.anchor_p && r.anchor_b == b.anchor_q
            } else if r.from == b.q && r.to == b.p {
                r.anchor_b == b.anchor_p && r.anchor_a == b.anchor_q
            } else {
                false
            }
        });
        match found {
            Some(bi) => {
                out[bi].reqs.push(i);
                of[i] = bi;
            }
            None => {
                of[i] = out.len();
                out.push(Bundle { reqs: vec![i], p: r.from, q: r.to, anchor_p: r.anchor_a, anchor_q: r.anchor_b });
            }
        }
    }
    (out, of)
}

// Extra cost of a detour segment: it is priced at the middle of its channel
// (an open side counts K + 20 deep), not at the hugging position.
fn detour_penalty(env: &Env, pts: &[(f64, f64)]) -> f64 {
    let mut pen = 0.0;
    let n = pts.len();
    if n < 4 {
        return 0.0;
    }
    for i in 1..n - 2 {
        let d0 = seg_dir(pts[i - 1], pts[i]);
        let d2 = seg_dir(pts[i + 1], pts[i + 2]);
        if d0 != (d2 + 2) % 4 {
            continue;
        }
        pen += channel_depth(env, pts[i], pts[i + 1], d0);
    }
    pen
}

// Free depth beyond a segment in direction `d` (towards the open side),
// capped at K + 20 when nothing bounds it.
fn channel_depth(env: &Env, p: (f64, f64), q: (f64, f64), d: usize) -> f64 {
    let k = env.k;
    let solids = env.solids();
    let horizontal = (p.1 - q.1).abs() < 1e-9;
    let (lo, hi) = if horizontal { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    let pos = if horizontal { p.1 } else { p.0 };
    let mut far = f64::INFINITY;
    for r in &solids {
        let (rlo, rhi, near) = if horizontal {
            (r.x0, r.x1, if d == 1 { r.y0 - pos } else { pos - r.y1 })
        } else {
            (r.y0, r.y1, if d == 0 { r.x0 - pos } else { pos - r.x1 })
        };
        if rlo < hi - EPS && rhi > lo + EPS && near >= -EPS {
            far = far.min(near);
        }
    }
    far.min(k + 20.0)
}

fn env_for(ctx: &Ctx, world: &World, a: usize, b: usize, k: f64) -> Env {
    Env { k, obs: crate::links::obstacles(ctx, world, a, b), a: world.rects[a], b: world.rects[b] }
}

// A side can hold `n` ports when they fit at half-clearance pitch.
fn side_fits(r: &Rect, s: Side, n: usize, k: f64) -> bool {
    if n <= 1 {
        return true;
    }
    side_len(r, s) - 2.0 * k >= (n as f64 - 1.0) * k / 2.0 - 1e-9
}

// The overlap of two facing sides' port ranges, if they face each other.
fn facing_overlap(a: &Rect, sa: Side, b: &Rect, sb: Side, k: f64) -> Option<(f64, f64)> {
    if (sa.idx() + 2) % 4 != sb.idx() {
        return None;
    }
    let (a0, a1) = side_span(a, sa);
    let (b0, b1) = side_span(b, sb);
    let lo = (a0 + k).max(b0 + k);
    let hi = (a1 - k).min(b1 - k);
    if lo > hi + 1e-9 {
        return None;
    }
    Some((lo, hi))
}

fn route_bundle(env: &Env, n: usize, anchor_p: Option<Side>, anchor_q: Option<Side>) -> Option<Path> {
    let sas: Vec<Side> = match anchor_p {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let sbs: Vec<Side> = match anchor_q {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let k = env.k;
    let mut best: Option<(f64, Path)> = None;
    for &sa in &sas {
        for &sb in &sbs {
            let pr = PortReq { sides_a: &[sa], sides_b: &[sb] };
            let Some(mut p) = search(env, &pr) else { continue };
            // capacity: a straight bundle needs the shared range, others each side
            let straight_ok = p.pts.len() <= 4
                && facing_overlap(&env.a, sa, &env.b, sb, k).map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
            if !straight_ok && !(side_fits(&env.a, sa, n, k) && side_fits(&env.b, sb, n, k)) {
                continue;
            }
            let c = p.cost + detour_penalty(env, &p.pts);
            if best.as_ref().map_or(true, |(bc, _)| c < *bc - 1e-9) {
                centre_staircases(env, &mut p.pts);
                best = Some((c, p));
            }
        }
    }
    best.map(|b| b.1)
}

// Corner radii: terminal segments can be used whole (after the marker
// pull-back), interior ones are shared half and half.
fn cap_radii(pts: &[(f64, f64)], want: &[f64], pull_s: f64, pull_e: f64) -> Vec<f64> {
    let n = pts.len();
    if n < 3 {
        return vec![];
    }
    let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
    let mut out = Vec::new();
    for c in 1..n - 1 {
        let before = if c == 1 { seg(0) - pull_s } else { seg(c - 1) / 2.0 };
        let after = if c == n - 2 { seg(c) - pull_e } else { seg(c) / 2.0 };
        out.push(want[c - 1].min(before).min(after).max(0.0));
    }
    out
}

fn stray() -> Routed {
    Routed { stray: true, pts: vec![], radii: vec![], curve: None, sa: None, sb: None }
}

pub fn route_links(ctx: &Ctx, world: &World, reqs: &[LinkReq]) -> Vec<Routed> {
    let mut out: Vec<Option<Routed>> = (0..reqs.len()).map(|_| None).collect();
    // natural and straight routing need no planning
    for (i, req) in reqs.iter().enumerate() {
        let a = world.rects[req.from];
        let b = world.rects[req.to];
        if req.routing == "straight" {
            let (p, q) = crate::links::stray_line(&a, &b);
            out[i] = Some(Routed { stray: false, pts: vec![p, q], radii: vec![], curve: None, sa: None, sb: None });
        } else if req.routing == "natural" {
            let (pts, curve, sa, sb) = natural(&a, &b, req);
            out[i] = Some(Routed { stray: false, pts, radii: vec![], curve: Some(curve), sa: Some(sa), sb: Some(sb) });
        } else if req.from == req.to {
            out[i] = Some(stray());
        }
    }
    let (bundles, _of) = bundles_of(reqs);
    for b in &bundles {
        let first = &reqs[b.reqs[0]];
        let k = first.k;
        let env = env_for(ctx, world, b.p, b.q, k);
        let n = b.reqs.len();
        let path = match route_bundle(&env, n, b.anchor_p, b.anchor_q) {
            Some(p) => p,
            None => {
                for &ri in &b.reqs {
                    out[ri] = Some(stray());
                }
                continue;
            }
        };
        // bundle order: forward links in order, then backward ones reversed
        let mut order: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from == b.p).collect();
        let mut back: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from != b.p).collect();
        back.reverse();
        order.extend(back);
        let wires = plan_bundle(&env, &path, n);
        for (slot, &ri) in order.iter().enumerate() {
            let req = &reqs[ri];
            let mut pts = wires[slot].0.clone();
            let mut want = wires[slot].1.clone();
            let (mut sa, mut sb) = (path.sa, path.sb);
            if req.from != b.p {
                pts.reverse();
                want.reverse();
                std::mem::swap(&mut sa, &mut sb);
            }
            let want: Vec<f64> = want.iter().map(|w| w + req.radius - k).collect();
            let radii = cap_radii(&pts, &want, req.pull_s, req.pull_e);
            out[ri] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(sa), sb: Some(sb) });
        }
    }
    out.into_iter().map(|o| o.unwrap_or_else(stray)).collect()
}

// Lay out `n` parallel wires along a bundle's route: spread ports on both
// end sides, stack the free segments. Returns per slot the polyline and the
// wanted corner radius (before capping) relative to the base radius K.
fn plan_bundle(env: &Env, path: &Path, n: usize) -> Vec<(Vec<(f64, f64)>, Vec<f64>)> {
    let k = env.k;
    let pts = &path.pts;
    let m = pts.len();
    // straight bundles: one shared range across both sides
    if m <= 4 {
        if let Some((lo, hi)) = facing_overlap(&env.a, path.sa, &env.b, path.sb, k) {
            if n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9 {
                let pitch = if n <= 1 { 0.0 } else { k.min((hi - lo) / (n as f64 - 1.0)) };
                let mid = (lo + hi) / 2.0;
                let t = tangent(path.sa);
                let sgn = if path.sa.horizontal() { t.0 } else { t.1 };
                let s = pts[0];
                let e = pts[m - 1];
                let mut v = Vec::new();
                for i in 0..n {
                    let off = (i as f64 - (n as f64 - 1.0) / 2.0) * pitch * sgn;
                    let c = mid + off;
                    let line = if path.sa.horizontal() { vec![(c, s.1), (c, e.1)] } else { vec![(s.0, c), (e.0, c)] };
                    v.push((line, vec![]));
                }
                return v;
            }
        }
    }
    // ports
    let pitch_of = |r: &Rect, s: Side| if n <= 1 { 0.0 } else { k.min((side_len(r, s) - 2.0 * k) / (n as f64 - 1.0)) };
    let pa = pitch_of(&env.a, path.sa);
    let pb = pitch_of(&env.b, path.sb);
    let ta = tangent(path.sa);
    let tb = tangent(path.sb);
    let mut lines: Vec<Vec<(f64, f64)>> = Vec::new();
    for i in 0..n {
        let c = i as f64 - (n as f64 - 1.0) / 2.0;
        let oa = c * pa;
        let ob = -c * pb;
        let mut w = pts.clone();
        // shift the first segment along A's side
        w[0].0 += ta.0 * oa;
        w[0].1 += ta.1 * oa;
        w[1].0 += ta.0 * oa;
        w[1].1 += ta.1 * oa;
        w[m - 1].0 += tb.0 * ob;
        w[m - 1].1 += tb.1 * ob;
        w[m - 2].0 += tb.0 * ob;
        w[m - 2].1 += tb.1 * ob;
        if m == 2 {
            // a straight route that cannot stay straight keeps its centre line
            w[1] = (pts[1].0 + tb.0 * ob, pts[1].1 + tb.1 * ob);
        }
        lines.push(w);
    }
    if m == 2 {
        return lines.into_iter().map(|l| (l, vec![])).collect();
    }
    // interior segments: stack parallel copies
    for j in 1..m - 2 {
        let u = seg_dir(pts[j - 1], pts[j]);
        let v = seg_dir(pts[j], pts[j + 1]);
        let w_next = seg_dir(pts[j + 1], pts[j + 2]);
        let uv = dvec(u);
        let vv = dvec(v);
        // rank: most offset towards v turns first
        let mut idx: Vec<usize> = (0..n).collect();
        let off = |i: usize| {
            let p = lines[i][j];
            p.0 * vv.0 + p.1 * vv.1
        };
        idx.sort_by(|&x, &y| off(y).partial_cmp(&off(x)).unwrap_or(std::cmp::Ordering::Equal).then(x.cmp(&y)));
        let base = pts[j];
        let base_u = base.0 * uv.0 + base.1 * uv.1;
        if w_next == (u + 2) % 4 {
            // U-turn: hug, stack outwards
            let depth = channel_depth(env, pts[j], pts[j + 1], u);
            let pitch = if n <= 1 { 0.0 } else { k.min(depth / (n as f64 - 1.0)) };
            for (rank, &i) in idx.iter().enumerate() {
                let pos = base_u + rank as f64 * pitch;
                set_pos(&mut lines[i], j, uv, pos);
            }
        } else {
            // staircase: centred in its channel
            let (lo, hi) = staircase_channel(env, pts, j);
            let width = hi - lo;
            let pitch = if n <= 1 { 0.0 } else { k.min(width / (n as f64 - 1.0)) };
            let mid = (lo + hi) / 2.0;
            for (rank, &i) in idx.iter().enumerate() {
                let pos = mid + (rank as f64 - (n as f64 - 1.0) / 2.0) * pitch;
                set_pos(&mut lines[i], j, uv, pos);
            }
        }
    }
    // nested corner radii relative to the inner wire at each corner
    let mut out = Vec::new();
    let mut wants: Vec<Vec<f64>> = vec![vec![k; m - 2]; n];
    for c in 1..m - 1 {
        // inner wire: the one whose corner is innermost (smallest leg sum)
        let pin = pts[c - 1];
        let pout = pts[c + 1];
        let _ = (pin, pout);
        let u = seg_dir(pts[c - 1], pts[c]);
        let v = seg_dir(pts[c], pts[c + 1]);
        let uv = dvec(u);
        let vv = dvec(v);
        // inner: largest offset towards v and smallest along u
        let score = |i: usize| {
            let p = lines[i][c];
            (p.0 * vv.0 + p.1 * vv.1) - (p.0 * uv.0 + p.1 * uv.1)
        };
        let mut inner = 0;
        for i in 1..n {
            if score(i) > score(inner) + 1e-9 {
                inner = i;
            }
        }
        let pc = lines[inner][c];
        for i in 0..n {
            let p = lines[i][c];
            wants[i][c - 1] = k + ((p.0 - pc.0).abs() + (p.1 - pc.1).abs()) / 2.0;
        }
    }
    for i in 0..n {
        out.push((lines[i].clone(), wants[i].clone()));
    }
    out
}

fn set_pos(line: &mut [(f64, f64)], j: usize, uv: (f64, f64), pos: f64) {
    // segment j runs between line[j] and line[j+1]; move it along u
    if uv.0.abs() > 0.5 {
        line[j].0 = pos * uv.0;
        line[j + 1].0 = pos * uv.0;
    } else {
        line[j].1 = pos * uv.1;
        line[j + 1].1 = pos * uv.1;
    }
}

// The channel a staircase segment can slide in (along the incoming
// direction's axis), as signed positions along u.
fn staircase_channel(env: &Env, pts: &[(f64, f64)], j: usize) -> (f64, f64) {
    let solids = env.solids();
    let p = pts[j];
    let q = pts[j + 1];
    let u = seg_dir(pts[j - 1], pts[j]);
    let uv = dvec(u);
    let vertical = (p.0 - q.0).abs() < 1e-9;
    let (lo0, hi0) = if vertical {
        let a = pts[j - 1].0;
        let b = pts[j + 2].0;
        (a.min(b), a.max(b))
    } else {
        let a = pts[j - 1].1;
        let b = pts[j + 2].1;
        (a.min(b), a.max(b))
    };
    let mut lo = lo0;
    let mut hi = hi0;
    if vertical {
        let (y0, y1) = (p.1.min(q.1), p.1.max(q.1));
        let x = p.0;
        for r in &solids {
            if r.y0 < y1 - EPS && r.y1 > y0 + EPS {
                if r.x1 <= x + EPS && r.x1 > lo {
                    lo = r.x1;
                }
                if r.x0 >= x - EPS && r.x0 < hi {
                    hi = r.x0;
                }
            }
        }
    } else {
        let (x0, x1) = (p.0.min(q.0), p.0.max(q.0));
        let y = p.1;
        for r in &solids {
            if r.x0 < x1 - EPS && r.x1 > x0 + EPS {
                if r.y1 <= y + EPS && r.y1 > lo {
                    lo = r.y1;
                }
                if r.y0 >= y - EPS && r.y0 < hi {
                    hi = r.y0;
                }
            }
        }
    }
    // signed along u
    let s = if vertical { uv.0 } else { uv.1 };
    if s >= 0.0 {
        (lo, hi)
    } else {
        (-hi, -lo)
    }
}

