    let horiz_seg = (p.1 - q.1).abs() < EPS;
    let (x0, x1) = if p.0 < q.0 { (p.0, q.0) } else { (q.0, p.0) };
    let (y0, y1) = if p.1 < q.1 { (p.1, q.1) } else { (q.1, p.1) };
