        };
        if !inter {
            continue;
        }
        // a horizontal border is crossed by vertical segments only
        if b.horiz == horiz_seg {
            return false;
        }
        let at = if horiz_seg { y0 } else { x0 };
        if at < b.lo - EPS || at > b.hi + EPS {
            return false;
        }
    }
    true
}

