    let a = env.a;
    let b = env.b;
    // grid lines
    let mut xs: Vec<f64> = Vec::new();
    let mut ys: Vec<f64> = Vec::new();
    for r in &solids {
        xs.push(r.x0);
        xs.push(r.x1);
        ys.push(r.y0);
        ys.push(r.y1);
    }
    for o in &env.obs {
        if o.kind == ObKind::Wall {
            let r = o.r;
            xs.push(r.x0 - k);
            xs.push(r.x0 + k);
            xs.push(r.x1 - k);
            xs.push(r.x1 + k);
            ys.push(r.y0 - k);
            ys.push(r.y0 + k);
            ys.push(r.y1 - k);
            ys.push(r.y1 + k);
        }
    }
    xs.push(a.cx());
    xs.push(b.cx());
    ys.push(a.cy());
    ys.push(b.cy());
    let xs = uniq(xs);
    let ys = uniq(ys);
    let nx = xs.len();
    let ny = ys.len();
    let xi = |x: f64| xs.iter().position(|v| (v - x).abs() < 1e-7);
    let yi = |y: f64| ys.iter().position(|v| (v - y).abs() < 1e-7);
    let vid = |i: usize, j: usize| j * nx + i;
    let nv = nx * ny;
    // vertex freedom
    let mut free = vec![true; nv];
    let mut banded = vec![false; nv];
    for j in 0..ny {
        for i in 0..nx {
            let (x, y) = (xs[i], ys[j]);
            if solids.iter().any(|r| r.contains_open(x, y)) {
                free[vid(i, j)] = false;
            }
            if in_band(&bands, x, y) {
                banded[vid(i, j)] = true;
            }
        }
    }
    // start / end stubs
    struct End {
