from sip import Sip13
T=int('05ddd672',16)
T4=int('61ec26de',16)
def outs(h):
    return {'lo':h&0xffffffff,'hi':h>>32,'fold':((h>>32)^h)&0xffffffff}
def check(h,label):
    for k,v in outs(h).items():
        if v==T: print('FOUND',label,k)
def fb(v): return struct.pack('<d',float(v))
def ub(v): return struct.pack('<Q',v)
items={'B':(-20,-2,40,4),'C':(-3,-6.5,6,13),'P':(-18,0,18,0),'S':(2,),'F':(10,),'L':(0,0),'Bx':(-20,-2,20,2),'Cx':(-3,-6.5,3,6.5),'W':(0,),'A':(0.5,)}
keys=list(items)
n=0
# raw f64 sequences, with/without length prefixes
for r in (1,2,3):
    for combo in itertools.permutations(keys,r):
        vals=[x for k in combo for x in items[k]]
        for mode in ('raw','lenpre','perlen'):
            h=Sip13()
            if mode=='raw':
                for x in vals: h.write(fb(x))
            elif mode=='lenpre':
                h.write(ub(len(vals)))
                for x in vals: h.write(fb(x))
            else:
                for k in combo:
                    h.write(ub(len(items[k])))
                    for x in items[k]: h.write(fb(x))
