// A U-turn segment already placed in a channel (for capacity checks).
#[derive(Clone, Debug)]
struct ChanUse {
    horiz: bool,
    pos: f64,
    u: usize,
    lo: f64,
    hi: f64,
    depth: f64,
    count: usize,
}

fn seg_span(p: (f64, f64), q: (f64, f64)) -> (bool, f64, f64, f64) {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    if horiz {
        (true, p.1, p.0.min(q.0), p.0.max(q.0))
    } else {
        (false, p.0, p.1.min(q.1), p.1.max(q.1))
    }
}

// U-turn segments of a path: (index, outward direction).
fn u_segments(pts: &[(f64, f64)]) -> Vec<(usize, usize)> {
    let m = pts.len();
    let mut v = Vec::new();
    if m < 4 {
        return v;
    }
    for j in 1..m - 2 {
        let d0 = seg_dir(pts[j - 1], pts[j]);
        let d2 = seg_dir(pts[j + 1], pts[j + 2]);
        if d0 == (d2 + 2) % 4 {
            v.push((j, d0));
        }
    }
    v
}

struct Occupancy {
    sides: std::collections::HashMap<(usize, usize), usize>,
    chans: Vec<ChanUse>,
}

fn route_bundle(env: &Env, n: usize, b: &Bundle, occ: &Occupancy) -> Option<Path> {
    let sas: Vec<Side> = match b.anchor_p {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let sbs: Vec<Side> = match b.anchor_q {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let k = env.k;
    let mut best: Option<(f64, Path)> = None;
    for &sa in &sas {
        for &sb in &sbs {
            let need = if n <= 1 { 0.0 } else { (n as f64 - 1.0) * k / 2.0 };
            let pr = PortReq { sides_a: &[sa], sides_b: &[sb], need };
            let Some(mut p) = search(env, &pr) else { continue };
            // sides: a straight bundle needs the shared range, others each
            // side (counting the wires already there)
            let straight_ok = p.pts.len() <= 4
                && facing_overlap(&env.a, sa, &env.b, sb, k).map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
            let na = occ.sides.get(&(b.p, sa.idx())).copied().unwrap_or(0) + n;
            let nb = occ.sides.get(&(b.q, sb.idx())).copied().unwrap_or(0) + n;
            if !straight_ok && !(side_fits(&env.a, sa, na, k) && side_fits(&env.b, sb, nb, k)) {
                continue;
            }
            // channels: U-turns stack in a channel of limited depth
            let mut chan_ok = true;
            for (j, u) in u_segments(&p.pts) {
                let (horiz, pos, lo, hi) = seg_span(p.pts[j], p.pts[j + 1]);
                let depth = channel_depth(env, p.pts[j], p.pts[j + 1], u);
                let m: usize = occ
                    .chans
                    .iter()
                    .filter(|c| c.horiz == horiz && (c.pos - pos).abs() < 1e-6 && c.u == u && c.lo < hi - EPS && c.hi > lo + EPS)
                    .map(|c| c.count)
                    .sum();
                let tot = m + n;
                if tot >= 2 && depth / (tot as f64 - 1.0) < k / 2.0 - 1e-9 {
                    chan_ok = false;
                }
            }
            if !chan_ok {
                continue;
            }
            let c = p.cost + detour_penalty(env, &p.pts);
            if best.as_ref().map_or(true, |(bc, _)| c < *bc - 1e-9) {
                centre_staircases(env, &mut p.pts);
                best = Some((c, p));
            }
        }
    }
    best.map(|b| b.1)
}

// Corner radii: terminal segments can be used whole (after the marker
// pull-back), interior ones are shared by their two corners in proportion
// to what they want.
fn cap_radii(pts: &[(f64, f64)], want: &[f64], pull_s: f64, pull_e: f64) -> Vec<f64> {
    let n = pts.len();
    if n < 3 {
        return vec![];
    }
    let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
    let share = |len: f64, mine: f64, other: f64| {
        if mine + other > len && mine + other > 0.0 {
            len * mine / (mine + other)
        } else {
            mine
        }
    };
    let mut out = Vec::new();
    for c in 1..n - 1 {
        let r = want[c - 1];
        let before = if c == 1 { seg(0) - pull_s } else { share(seg(c - 1), r, want[c - 2]) };
        let after = if c == n - 2 { seg(c) - pull_e } else { share(seg(c), r, want[c]) };
        out.push(r.min(before).min(after).max(0.0));
    }
    out
}

fn stray() -> Routed {
    Routed { stray: true, pts: vec![], radii: vec![], curve: None, sa: None, sb: None }
}

// One wire being planned.
#[derive(Clone, Debug)]
struct W {
    req: usize,
    bundle: usize,
    slot: usize,
    // polyline from the (promoted) start node to the end node
    pts: Vec<(f64, f64)>,
    sa: Side,
    sb: Side,
    from: usize,
    to: usize,
    k: f64,
    // logical offsets per segment (ports and tracks), for nested radii
    offs: Vec<f64>,
    straight: bool,
}

pub fn route_links(ctx: &Ctx, world: &World, reqs: &[LinkReq]) -> Vec<Routed> {
    let mut out: Vec<Option<Routed>> = (0..reqs.len()).map(|_| None).collect();
    // natural and straight routing need no planning
    for (i, req) in reqs.iter().enumerate() {
        let a = world.rects[req.from];
        let b = world.rects[req.to];
        if req.routing == "straight" {
            let (p, q) = crate::links::stray_line(&a, &b);
            out[i] = Some(Routed { stray: false, pts: vec![p, q], radii: vec![], curve: None, sa: None, sb: None });
        } else if req.routing == "natural" {
            let (pts, curve, sa, sb) = natural(&a, &b, req);
            out[i] = Some(Routed { stray: false, pts, radii: vec![], curve: Some(curve), sa: Some(sa), sb: Some(sb) });
        } else if req.from == req.to {
            out[i] = Some(stray());
        }
    }
    let (bundles, _of) = bundles_of(reqs);
    let mut occ = Occupancy { sides: std::collections::HashMap::new(), chans: Vec::new() };
    let mut wires: Vec<W> = Vec::new();
    let mut envs: Vec<Env> = Vec::new();
    for (bi, b) in bundles.iter().enumerate() {
        let first = &reqs[b.reqs[0]];
        let k = first.k;
        let env = env_for(ctx, world, b.p, b.q, k);
        let n = b.reqs.len();
        let path = route_bundle(&env, n, b, &occ);
        let Some(path) = path else {
            for &ri in &b.reqs {
                out[ri] = Some(stray());
            }
            envs.push(env);
            continue;
        };
        *occ.sides.entry((b.p, path.sa.idx())).or_insert(0) += n;
        *occ.sides.entry((b.q, path.sb.idx())).or_insert(0) += n;
        for (j, u) in u_segments(&path.pts) {
            let (horiz, pos, lo, hi) = seg_span(path.pts[j], path.pts[j + 1]);
            let depth = channel_depth(&env, path.pts[j], path.pts[j + 1], u);
            occ.chans.push(ChanUse { horiz, pos, u, lo, hi, depth, count: n });
        }
        let straight = path.pts.len() <= 4
            && facing_overlap(&env.a, path.sa, &env.b, path.sb, k).map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
        // bundle order: forward links in order, then backward ones reversed
        let mut order: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from == b.p).collect();
        let mut back: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from != b.p).collect();
        back.reverse();
        order.extend(back);
        for (slot, &ri) in order.iter().enumerate() {
            let pts = path.pts.clone();
            let m = pts.len();
            wires.push(W { req: ri, bundle: bi, slot, pts, sa: path.sa, sb: path.sb, from: b.p, to: b.q, k, offs: vec![0.0; m - 1], straight });
        }
        envs.push(env);
    }
    plan_ports(world, &bundles, &mut wires);
    plan_tracks(&envs, &mut wires);
    // nested radii within each bundle, then orient each wire as its link
    for bi in 0..bundles.len() {
        let ids: Vec<usize> = (0..wires.len()).filter(|&w| wires[w].bundle == bi).collect();
        if ids.is_empty() {
            continue;
        }
        let m = wires[ids[0]].pts.len();
        let mut wants: Vec<Vec<f64>> = vec![vec![0.0; m.saturating_sub(2)]; ids.len()];
        if m >= 3 && !wires[ids[0]].straight {
            for c in 1..m - 1 {
                let u = seg_dir(wires[ids[0]].pts[c - 1], wires[ids[0]].pts[c]);
                let v = seg_dir(wires[ids[0]].pts[c], wires[ids[0]].pts[c + 1]);
                let uv = dvec(u);
                let vv = dvec(v);
                let score = |w: usize| {
                    let p = wires[w].pts[c];
                    (p.0 * vv.0 + p.1 * vv.1) - (p.0 * uv.0 + p.1 * uv.1)
                };
                let mut inner = ids[0];
                for &w in &ids[1..] {
                    if score(w) > score(inner) + 1e-9 {
                        inner = w;
                    }
                }
                for (x, &w) in ids.iter().enumerate() {
                    wants[x][c - 1] = ((wires[w].offs[c - 1] - wires[inner].offs[c - 1]).abs() + (wires[w].offs[c] - wires[inner].offs[c]).abs()) / 2.0;
                }
            }
        }
        for (x, &w) in ids.iter().enumerate() {
            let wr = &wires[w];
            let req = &reqs[wr.req];
            let mut pts = wr.pts.clone();
            let mut want = wants[x].clone();
            let (mut sa, mut sb) = (wr.sa, wr.sb);
            if req.from != wr.from {
                pts.reverse();
                want.reverse();
                std::mem::swap(&mut sa, &mut sb);
            }
            let want: Vec<f64> = want.iter().map(|d| req.radius + d).collect();
            let radii = if wr.straight { vec![] } else { cap_radii(&pts, &want, req.pull_s, req.pull_e) };
            out[wr.req] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(sa), sb: Some(sb) });
        }
    }
    out.into_iter().map(|o| o.unwrap_or_else(stray)).collect()
}

// Where the wire end at `end` (0 start, 1 finish) leaves its side: the
// turn class relative to the side's clockwise tangent and the distance to
// the first turn.
fn end_shape(w: &W, end: usize) -> (i32, f64) {
    let pts: Vec<(f64, f64)> = if end == 0 { w.pts.clone() } else { w.pts.iter().rev().cloned().collect() };
    let side = if end == 0 { w.sa } else { w.sb };
    if pts.len() <= 2 || w.straight {
        return (0, 0.0);
    }
    let t = tangent(side);
    let nd = dvec(seg_dir(pts[1], pts[2]));
    let dot = nd.0 * t.0 + nd.1 * t.1;
    let cls = if dot > 0.5 {
        1
    } else if dot < -0.5 {
        -1
    } else {
        0
    };
    let dist = (pts[1].0 - pts[0].0).abs() + (pts[1].1 - pts[0].1).abs();
    (cls, dist)
}

// Spread every side's wire ends: ordered so wires do not cross, centred,
// pitch the clearance (squeezed down to fit the side).
fn plan_ports(world: &World, bundles: &[Bundle], wires: &mut [W]) {
    use std::collections::BTreeMap;
    let mut sides: BTreeMap<(usize, usize), Vec<(usize, usize)>> = BTreeMap::new();
    for (wi, w) in wires.iter().enumerate() {
        sides.entry((w.from, w.sa.idx())).or_default().push((wi, 0));
        sides.entry((w.to, w.sb.idx())).or_default().push((wi, 1));
    }
    // straight wires keep one position on both sides: the busier side decides
    let mut straight_pos: std::collections::HashMap<usize, f64> = std::collections::HashMap::new();
    let mut entries: Vec<((usize, usize), Vec<(usize, usize)>)> = sides.into_iter().collect();
    // busier sides first so straight wires take their positions there
    entries.sort_by(|a, b| b.1.len().cmp(&a.1.len()).then(a.0.cmp(&b.0)));
    for ((node, sidx), mut ends) in entries {
        let side = [Side::Top, Side::Right, Side::Bottom, Side::Left][sidx];
        let r = world.rects[node];
        let k = wires[ends[0].0].k;
        ends.sort_by(|&(wa, ea), &(wb, eb)| {
            let (ca, da) = end_shape(&wires[wa], ea);
            let (cb, db) = end_shape(&wires[wb], eb);
            let ka = if ca == -1 { da } else if ca == 1 { -da } else { 0.0 };
            let kb = if cb == -1 { db } else if cb == 1 { -db } else { 0.0 };
            let ba = wires[wa].bundle;
            let bb = wires[wb].bundle;
            // within a bundle: slot order on the start side, reversed on the far side
            let sa = if ea == 0 { wires[wa].slot as i64 } else { -(wires[wa].slot as i64) };
            let sb = if eb == 0 { wires[wb].slot as i64 } else { -(wires[wb].slot as i64) };
            ca.cmp(&cb)
                .then(ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal))
                .then(ba.cmp(&bb))
                .then(sa.cmp(&sb))
        });
        let n = ends.len();
        let len = if side.horizontal() { r.w() } else { r.h() };
        let pitch = if n <= 1 { 0.0 } else { k.min((len - 2.0 * k) / (n as f64 - 1.0)) };
        let t = tangent(side);
        for (i, &(wi, e)) in ends.iter().enumerate() {
            let c = i as f64 - (n as f64 - 1.0) / 2.0;
            let mut off = c * pitch;
            let w = &wires[wi];
            if w.straight {
                if let Some(&pos) = straight_pos.get(&wi) {
                    // already fixed by the other side: convert to an offset here
                    let base = if side.horizontal() { r.cx() } else { r.cy() };
                    let sgn = if side.horizontal() { t.0 } else { t.1 };
                    off = (pos - base) * sgn;
                }
            }
            apply_port(&mut wires[wi], e, t, off);
            let w = &wires[wi];
            if w.straight && !straight_pos.contains_key(&wi) {
                let p = if e == 0 { w.pts[0] } else { *w.pts.last().unwrap() };
                straight_pos.insert(wi, if side.horizontal() { p.0 } else { p.1 });
            }
        }
    }
    let _ = bundles;
}

fn apply_port(w: &mut W, end: usize, t: (f64, f64), off: f64) {
    let m = w.pts.len();
    if w.straight {
        // the whole line moves; it stays straight
        let s = w.pts[0];
        let e = w.pts[m - 1];
        let horiz_line = (s.1 - e.1).abs() < 1e-9 || m > 2;
        let _ = horiz_line;
        let base = if end == 0 { s } else { e };
        let target = (base.0 + t.0 * off, base.1 + t.1 * off);
        // a straight wire is a 2-point line between facing sides
        let (sp, ep) = if t.0.abs() > 0.5 {
            ((target.0, s.1), (target.0, e.1))
        } else {
            ((s.0, target.1), (e.0, target.1))
        };
        w.pts = vec![sp, ep];
        w.offs = vec![off];
        return;
    }
    if end == 0 {
        w.pts[0].0 += t.0 * off;
        w.pts[0].1 += t.1 * off;
        w.pts[1].0 += t.0 * off;
        w.pts[1].1 += t.1 * off;
        w.offs[0] = off;
    } else {
        w.pts[m - 1].0 += t.0 * off;
        w.pts[m - 1].1 += t.1 * off;
        w.pts[m - 2].0 += t.0 * off;
        w.pts[m - 2].1 += t.1 * off;
        w.offs[m - 2] = -off;
    }
}

// Stack parallel interior segments: U-turns hug what they go around and
// stack outwards, staircases centre in their channel.
fn plan_tracks(envs: &[Env], wires: &mut [W]) {
    // collect interior segments
    struct Seg {
        w: usize,
        j: usize,
        u: usize,
        horiz: bool,
        pos: f64,
        lo: f64,
        hi: f64,
        is_u: bool,
        chan: (f64, f64),
    }
    let mut segs: Vec<Seg> = Vec::new();
    for (wi, w) in wires.iter().enumerate() {
        if w.straight {
            continue;
        }
        let m = w.pts.len();
        if m < 4 {
            continue;
        }
        for j in 1..m - 2 {
            let d0 = seg_dir(w.pts[j - 1], w.pts[j]);
            let d2 = seg_dir(w.pts[j + 1], w.pts[j + 2]);
            let (horiz, pos, lo, hi) = seg_span(w.pts[j], w.pts[j + 1]);
            let is_u = d0 == (d2 + 2) % 4;
            let chan = if is_u { (0.0, 0.0) } else { staircase_channel(&envs[w.bundle], &w.pts, j) };
            segs.push(Seg { w: wi, j, u: d0, horiz, pos, lo, hi, is_u, chan });
        }
    }
    // group by channel (union of overlapping spans)
    let n = segs.len();
    let mut group: Vec<usize> = (0..n).collect();
    fn find(g: &mut Vec<usize>, x: usize) -> usize {
        let mut r = x;
        while g[r] != r {
            r = g[r];
        }
        let mut c = x;
        while g[c] != r {
            let nx = g[c];
            g[c] = r;
            c = nx;
        }
        r
    }
    for a in 0..n {
        for b in a + 1..n {
            let (sa, sb) = (&segs[a], &segs[b]);
            if sa.is_u != sb.is_u || sa.horiz != sb.horiz || sa.u != sb.u {
                continue;
            }
            let same = if sa.is_u { (sa.pos - sb.pos).abs() < 1e-6 } else { (sa.chan.0 - sb.chan.0).abs() < 1e-6 && (sa.chan.1 - sb.chan.1).abs() < 1e-6 };
            if same && sa.lo < sb.hi - EPS && sb.lo < sa.hi - EPS {
                let ra = find(&mut group, a);
                let rb = find(&mut group, b);
                if ra != rb {
                    group[rb] = ra;
                }
            }
        }
    }
    let mut groups: std::collections::BTreeMap<usize, Vec<usize>> = std::collections::BTreeMap::new();
    for i in 0..n {
        let r = find(&mut group, i);
        groups.entry(r).or_default().push(i);
    }
    for (_, members) in groups {
        let first = &segs[members[0]];
        let k = wires[first.w].k;
        let cnt = members.len();
        let uv = dvec(first.u);
        // current spans (after ports)
        let span = |s: &Seg, ws: &[W]| {
            let w = &ws[s.w];
            let (_, _, lo, hi) = seg_span(w.pts[s.j], w.pts[s.j + 1]);
            (lo, hi)
        };
        // nesting order, inner first
        let mut left: Vec<usize> = members.clone();
        let mut ordered: Vec<usize> = Vec::new();
        while !left.is_empty() {
            let mut cands: Vec<usize> = Vec::new();
            for &x in &left {
                let (xl, xh) = span(&segs[x], wires);
                let contains_other = left.iter().any(|&y| {
                    if y == x {
                        return false;
                    }
                    let (yl, yh) = span(&segs[y], wires);
                    yl > xl + 1e-6 && yh < xh - 1e-6
                });
                if !contains_other {
                    cands.push(x);
                }
            }
            if cands.is_empty() {
                cands = left.clone();
            }
            // ties: the wire most offset towards where it turns goes first
            let key = |x: usize| {
                let s = &segs[x];
                let w = &wires[s.w];
                let v = dvec(seg_dir(w.pts[s.j], w.pts[s.j + 1]));
                let p = w.pts[s.j];
                (w.bundle, -(p.0 * v.0 + p.1 * v.1))
            };
            cands.sort_by(|&a, &b| {
                let (ba, oa) = key(a);
                let (bb, ob) = key(b);
                ba.cmp(&bb).then(oa.partial_cmp(&ob).unwrap_or(std::cmp::Ordering::Equal))
            });
            let pick = cands[0];
            ordered.push(pick);
            left.retain(|&x| x != pick);
        }
        if first.is_u {
            let depth = {
                let w = &wires[first.w];
                channel_depth(&envs[w.bundle], w.pts[first.j], w.pts[first.j + 1], first.u)
            };
            let pitch = if cnt <= 1 { 0.0 } else { k.min(depth / (cnt as f64 - 1.0)) };
            let base = first.pos * (if first.horiz { uv.1 } else { uv.0 });
            for (rank, &x) in ordered.iter().enumerate() {
                let s = &segs[x];
                let o = rank as f64 * pitch;
                set_pos(&mut wires[s.w].pts, s.j, uv, base + o);
                wires[s.w].offs[s.j] = o;
            }
        } else {
            let (lo, hi) = first.chan;
            let width = hi - lo;
            let pitch = if cnt <= 1 { 0.0 } else { k.min(width / (cnt as f64 - 1.0)) };
            let mid = (lo + hi) / 2.0;
            for (rank, &x) in ordered.iter().enumerate() {
                let s = &segs[x];
                let o = (rank as f64 - (cnt as f64 - 1.0) / 2.0) * pitch;
                set_pos(&mut wires[s.w].pts, s.j, uv, mid + o);
                wires[s.w].offs[s.j] = o;
            }
        }
    }
}

// A U-turn segment already placed in a channel (for capacity checks).
#[derive(Clone, Debug)]
struct ChanUse {
    horiz: bool,
    pos: f64,
    u: usize,
    lo: f64,
    hi: f64,
    depth: f64,
    count: usize,
}

fn seg_span(p: (f64, f64), q: (f64, f64)) -> (bool, f64, f64, f64) {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    if horiz {
        (true, p.1, p.0.min(q.0), p.0.max(q.0))
    } else {
        (false, p.0, p.1.min(q.1), p.1.max(q.1))
    }
}

// U-turn segments of a path: (index, outward direction).
fn u_segments(pts: &[(f64, f64)]) -> Vec<(usize, usize)> {
    let m = pts.len();
    let mut v = Vec::new();
    if m < 4 {
        return v;
    }
    for j in 1..m - 2 {
        let d0 = seg_dir(pts[j - 1], pts[j]);
        let d2 = seg_dir(pts[j + 1], pts[j + 2]);
        if d0 == (d2 + 2) % 4 {
            v.push((j, d0));
        }
    }
    v
}

struct Occupancy {
    sides: std::collections::HashMap<(usize, usize), usize>,
    chans: Vec<ChanUse>,
}

fn route_bundle(env: &Env, n: usize, b: &Bundle, occ: &Occupancy) -> Option<Path> {
    let sas: Vec<Side> = match b.anchor_p {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let sbs: Vec<Side> = match b.anchor_q {
        Some(s) => vec![s],
        None => ORDER.to_vec(),
    };
    let k = env.k;
    let mut best: Option<(f64, Path)> = None;
    for &sa in &sas {
        for &sb in &sbs {
            let need = if n <= 1 { 0.0 } else { (n as f64 - 1.0) * k / 2.0 };
            let pr = PortReq { sides_a: &[sa], sides_b: &[sb], need };
            let Some(mut p) = search(env, &pr) else { continue };
            // sides: a straight bundle needs the shared range, others each
            // side (counting the wires already there)
            let straight_ok = p.pts.len() <= 4
                && facing_overlap(&env.a, sa, &env.b, sb, k).map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
            let na = occ.sides.get(&(b.p, sa.idx())).copied().unwrap_or(0) + n;
            let nb = occ.sides.get(&(b.q, sb.idx())).copied().unwrap_or(0) + n;
            if !straight_ok && !(side_fits(&env.a, sa, na, k) && side_fits(&env.b, sb, nb, k)) {
                continue;
            }
            // channels: U-turns stack in a channel of limited depth
            let mut chan_ok = true;
            for (j, u) in u_segments(&p.pts) {
                let (horiz, pos, lo, hi) = seg_span(p.pts[j], p.pts[j + 1]);
                let depth = channel_depth(env, p.pts[j], p.pts[j + 1], u);
                let m: usize = occ
                    .chans
                    .iter()
                    .filter(|c| c.horiz == horiz && (c.pos - pos).abs() < 1e-6 && c.u == u && c.lo < hi - EPS && c.hi > lo + EPS)
                    .map(|c| c.count)
                    .sum();
                let tot = m + n;
                if tot >= 2 && depth / (tot as f64 - 1.0) < k / 2.0 - 1e-9 {
                    chan_ok = false;
                }
            }
            if !chan_ok {
                continue;
            }
            let c = p.cost + detour_penalty(env, &p.pts);
            if best.as_ref().map_or(true, |(bc, _)| c < *bc - 1e-9) {
                centre_staircases(env, &mut p.pts);
                best = Some((c, p));
            }
        }
    }
    best.map(|b| b.1)
}

// Corner radii: terminal segments can be used whole (after the marker
// pull-back), interior ones are shared by their two corners in proportion
// to what they want.
fn cap_radii(pts: &[(f64, f64)], want: &[f64], pull_s: f64, pull_e: f64) -> Vec<f64> {
    let n = pts.len();
    if n < 3 {
        return vec![];
    }
    let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
    let share = |len: f64, mine: f64, other: f64| {
        if mine + other > len && mine + other > 0.0 {
            len * mine / (mine + other)
        } else {
            mine
        }
    };
    let mut out = Vec::new();
    for c in 1..n - 1 {
        let r = want[c - 1];
        let before = if c == 1 { seg(0) - pull_s } else { share(seg(c - 1), r, want[c - 2]) };
        let after = if c == n - 2 { seg(c) - pull_e } else { share(seg(c), r, want[c]) };
        out.push(r.min(before).min(after).max(0.0));
    }
    out
}

fn stray() -> Routed {
    Routed { stray: true, pts: vec![], radii: vec![], curve: None, sa: None, sb: None }
}

// One wire being planned.
#[derive(Clone, Debug)]
struct W {
    req: usize,
    bundle: usize,
    slot: usize,
    // polyline from the (promoted) start node to the end node
    pts: Vec<(f64, f64)>,
    sa: Side,
    sb: Side,
    from: usize,
    to: usize,
    k: f64,
    // logical offsets per segment (ports and tracks), for nested radii
    offs: Vec<f64>,
    straight: bool,
}

pub fn route_links(ctx: &Ctx, world: &World, reqs: &[LinkReq]) -> Vec<Routed> {
    let mut out: Vec<Option<Routed>> = (0..reqs.len()).map(|_| None).collect();
    // natural and straight routing need no planning
    for (i, req) in reqs.iter().enumerate() {
        let a = world.rects[req.from];
        let b = world.rects[req.to];
        if req.routing == "straight" {
            let (p, q) = crate::links::stray_line(&a, &b);
            out[i] = Some(Routed { stray: false, pts: vec![p, q], radii: vec![], curve: None, sa: None, sb: None });
        } else if req.routing == "natural" {
            let (pts, curve, sa, sb) = natural(&a, &b, req);
            out[i] = Some(Routed { stray: false, pts, radii: vec![], curve: Some(curve), sa: Some(sa), sb: Some(sb) });
        } else if req.from == req.to {
            out[i] = Some(stray());
        }
    }
    let (bundles, _of) = bundles_of(reqs);
    let mut occ = Occupancy { sides: std::collections::HashMap::new(), chans: Vec::new() };
    let mut wires: Vec<W> = Vec::new();
    let mut envs: Vec<Env> = Vec::new();
    for (bi, b) in bundles.iter().enumerate() {
        let first = &reqs[b.reqs[0]];
        let k = first.k;
        let env = env_for(ctx, world, b.p, b.q, k);
        let n = b.reqs.len();
        let path = route_bundle(&env, n, b, &occ);
        let Some(path) = path else {
            for &ri in &b.reqs {
                out[ri] = Some(stray());
            }
            envs.push(env);
            continue;
        };
        *occ.sides.entry((b.p, path.sa.idx())).or_insert(0) += n;
        *occ.sides.entry((b.q, path.sb.idx())).or_insert(0) += n;
        for (j, u) in u_segments(&path.pts) {
            let (horiz, pos, lo, hi) = seg_span(path.pts[j], path.pts[j + 1]);
            let depth = channel_depth(&env, path.pts[j], path.pts[j + 1], u);
            occ.chans.push(ChanUse { horiz, pos, u, lo, hi, depth, count: n });
        }
        let straight = path.pts.len() <= 4
            && facing_overlap(&env.a, path.sa, &env.b, path.sb, k).map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
        // bundle order: forward links in order, then backward ones reversed
        let mut order: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from == b.p).collect();
        let mut back: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from != b.p).collect();
        back.reverse();
        order.extend(back);
        for (slot, &ri) in order.iter().enumerate() {
            let pts = path.pts.clone();
            let m = pts.len();
            wires.push(W { req: ri, bundle: bi, slot, pts, sa: path.sa, sb: path.sb, from: b.p, to: b.q, k, offs: vec![0.0; m - 1], straight });
        }
        envs.push(env);
    }
    plan_ports(world, &bundles, &mut wires);
    plan_tracks(&envs, &mut wires);
    // nested radii within each bundle, then orient each wire as its link
    for bi in 0..bundles.len() {
        let ids: Vec<usize> = (0..wires.len()).filter(|&w| wires[w].bundle == bi).collect();
        if ids.is_empty() {
            continue;
        }
        let m = wires[ids[0]].pts.len();
        let mut wants: Vec<Vec<f64>> = vec![vec![0.0; m.saturating_sub(2)]; ids.len()];
        if m >= 3 && !wires[ids[0]].straight {
            for c in 1..m - 1 {
                let u = seg_dir(wires[ids[0]].pts[c - 1], wires[ids[0]].pts[c]);
                let v = seg_dir(wires[ids[0]].pts[c], wires[ids[0]].pts[c + 1]);
                let uv = dvec(u);
                let vv = dvec(v);
                let score = |w: usize| {
                    let p = wires[w].pts[c];
                    (p.0 * vv.0 + p.1 * vv.1) - (p.0 * uv.0 + p.1 * uv.1)
                };
                let mut inner = ids[0];
                for &w in &ids[1..] {
                    if score(w) > score(inner) + 1e-9 {
                        inner = w;
                    }
                }
                for (x, &w) in ids.iter().enumerate() {
                    wants[x][c - 1] = ((wires[w].offs[c - 1] - wires[inner].offs[c - 1]).abs() + (wires[w].offs[c] - wires[inner].offs[c]).abs()) / 2.0;
                }
            }
        }
        for (x, &w) in ids.iter().enumerate() {
            let wr = &wires[w];
            let req = &reqs[wr.req];
            let mut pts = wr.pts.clone();
            let mut want = wants[x].clone();
            let (mut sa, mut sb) = (wr.sa, wr.sb);
            if req.from != wr.from {
                pts.reverse();
                want.reverse();
                std::mem::swap(&mut sa, &mut sb);
            }
            let want: Vec<f64> = want.iter().map(|d| req.radius + d).collect();
            let radii = if wr.straight { vec![] } else { cap_radii(&pts, &want, req.pull_s, req.pull_e) };
            out[wr.req] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(sa), sb: Some(sb) });
        }
    }
    out.into_iter().map(|o| o.unwrap_or_else(stray)).collect()
}

// Where the wire end at `end` (0 start, 1 finish) leaves its side: the
// turn class relative to the side's clockwise tangent and the distance to
// the first turn.
fn end_shape(w: &W, end: usize) -> (i32, f64) {
    let pts: Vec<(f64, f64)> = if end == 0 { w.pts.clone() } else { w.pts.iter().rev().cloned().collect() };
    let side = if end == 0 { w.sa } else { w.sb };
    if pts.len() <= 2 || w.straight {
        return (0, 0.0);
    }
    let t = tangent(side);
    let nd = dvec(seg_dir(pts[1], pts[2]));
    let dot = nd.0 * t.0 + nd.1 * t.1;
    let cls = if dot > 0.5 {
        1
    } else if dot < -0.5 {
        -1
    } else {
        0
    };
    let dist = (pts[1].0 - pts[0].0).abs() + (pts[1].1 - pts[0].1).abs();
    (cls, dist)
}

// Spread every side's wire ends: ordered so wires do not cross, centred,
// pitch the clearance (squeezed down to fit the side).
fn plan_ports(world: &World, bundles: &[Bundle], wires: &mut [W]) {
    use std::collections::BTreeMap;
    let mut sides: BTreeMap<(usize, usize), Vec<(usize, usize)>> = BTreeMap::new();
    for (wi, w) in wires.iter().enumerate() {
        sides.entry((w.from, w.sa.idx())).or_default().push((wi, 0));
        sides.entry((w.to, w.sb.idx())).or_default().push((wi, 1));
    }
    // straight wires keep one position on both sides: the busier side decides
    let mut straight_pos: std::collections::HashMap<usize, f64> = std::collections::HashMap::new();
    let mut entries: Vec<((usize, usize), Vec<(usize, usize)>)> = sides.into_iter().collect();
    // busier sides first so straight wires take their positions there
    entries.sort_by(|a, b| b.1.len().cmp(&a.1.len()).then(a.0.cmp(&b.0)));
    for ((node, sidx), mut ends) in entries {
        let side = [Side::Top, Side::Right, Side::Bottom, Side::Left][sidx];
        let r = world.rects[node];
        let k = wires[ends[0].0].k;
        ends.sort_by(|&(wa, ea), &(wb, eb)| {
            let (ca, da) = end_shape(&wires[wa], ea);
            let (cb, db) = end_shape(&wires[wb], eb);
            let ka = if ca == -1 { da } else if ca == 1 { -da } else { 0.0 };
            let kb = if cb == -1 { db } else if cb == 1 { -db } else { 0.0 };
            let ba = wires[wa].bundle;
            let bb = wires[wb].bundle;
            // within a bundle: slot order on the start side, reversed on the far side
            let sa = if ea == 0 { wires[wa].slot as i64 } else { -(wires[wa].slot as i64) };
            let sb = if eb == 0 { wires[wb].slot as i64 } else { -(wires[wb].slot as i64) };
            ca.cmp(&cb)
                .then(ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal))
                .then(ba.cmp(&bb))
                .then(sa.cmp(&sb))
        });
        let n = ends.len();
        let len = if side.horizontal() { r.w() } else { r.h() };
        let pitch = if n <= 1 { 0.0 } else { k.min((len - 2.0 * k) / (n as f64 - 1.0)) };
        let t = tangent(side);
        for (i, &(wi, e)) in ends.iter().enumerate() {
            let c = i as f64 - (n as f64 - 1.0) / 2.0;
            let mut off = c * pitch;
            let w = &wires[wi];
            if w.straight {
                if let Some(&pos) = straight_pos.get(&wi) {
                    // already fixed by the other side: convert to an offset here
                    let base = if side.horizontal() { r.cx() } else { r.cy() };
                    let sgn = if side.horizontal() { t.0 } else { t.1 };
                    off = (pos - base) * sgn;
                }
            }
            apply_port(&mut wires[wi], e, t, off);
            let w = &wires[wi];
            if w.straight && !straight_pos.contains_key(&wi) {
                let p = if e == 0 { w.pts[0] } else { *w.pts.last().unwrap() };
                straight_pos.insert(wi, if side.horizontal() { p.0 } else { p.1 });
            }
        }
    }
    let _ = bundles;
}

fn apply_port(w: &mut W, end: usize, t: (f64, f64), off: f64) {
    let m = w.pts.len();
    if w.straight {
        // the whole line moves; it stays straight
        let s = w.pts[0];
        let e = w.pts[m - 1];
        let horiz_line = (s.1 - e.1).abs() < 1e-9 || m > 2;
        let _ = horiz_line;
        let base = if end == 0 { s } else { e };
        let target = (base.0 + t.0 * off, base.1 + t.1 * off);
        // a straight wire is a 2-point line between facing sides
        let (sp, ep) = if t.0.abs() > 0.5 {
            ((target.0, s.1), (target.0, e.1))
        } else {
            ((s.0, target.1), (e.0, target.1))
        };
        w.pts = vec![sp, ep];
        w.offs = vec![off];
        return;
    }
    if end == 0 {
        w.pts[0].0 += t.0 * off;
        w.pts[0].1 += t.1 * off;
        w.pts[1].0 += t.0 * off;
        w.pts[1].1 += t.1 * off;
        w.offs[0] = off;
    } else {
        w.pts[m - 1].0 += t.0 * off;
        w.pts[m - 1].1 += t.1 * off;
        w.pts[m - 2].0 += t.0 * off;
        w.pts[m - 2].1 += t.1 * off;
        w.offs[m - 2] = -off;
    }
}

// Stack parallel interior segments: U-turns hug what they go around and
// stack outwards, staircases centre in their channel.
fn plan_tracks(envs: &[Env], wires: &mut [W]) {
    // collect interior segments
    struct Seg {
        w: usize,
        j: usize,
        u: usize,
        horiz: bool,
        pos: f64,
        lo: f64,
        hi: f64,
        is_u: bool,
        chan: (f64, f64),
    }
    let mut segs: Vec<Seg> = Vec::new();
    for (wi, w) in wires.iter().enumerate() {
        if w.straight {
            continue;
        }
        let m = w.pts.len();
        if m < 4 {
            continue;
        }
        for j in 1..m - 2 {
            let d0 = seg_dir(w.pts[j - 1], w.pts[j]);
            let d2 = seg_dir(w.pts[j + 1], w.pts[j + 2]);
            let (horiz, pos, lo, hi) = seg_span(w.pts[j], w.pts[j + 1]);
            let is_u = d0 == (d2 + 2) % 4;
            let chan = if is_u { (0.0, 0.0) } else { staircase_channel(&envs[w.bundle], &w.pts, j) };
            segs.push(Seg { w: wi, j, u: d0, horiz, pos, lo, hi, is_u, chan });
        }
    }
    // group by channel (union of overlapping spans)
    let n = segs.len();
    let mut group: Vec<usize> = (0..n).collect();
    fn find(g: &mut Vec<usize>, x: usize) -> usize {
        let mut r = x;
        while g[r] != r {
            r = g[r];
        }
        let mut c = x;
        while g[c] != r {
            let nx = g[c];
            g[c] = r;
            c = nx;
        }
        r
    }
    for a in 0..n {
        for b in a + 1..n {
            let (sa, sb) = (&segs[a], &segs[b]);
            if sa.is_u != sb.is_u || sa.horiz != sb.horiz || sa.u != sb.u {
                continue;
            }
            let same = if sa.is_u { (sa.pos - sb.pos).abs() < 1e-6 } else { (sa.chan.0 - sb.chan.0).abs() < 1e-6 && (sa.chan.1 - sb.chan.1).abs() < 1e-6 };
            if same && sa.lo < sb.hi - EPS && sb.lo < sa.hi - EPS {
                let ra = find(&mut group, a);
                let rb = find(&mut group, b);
                if ra != rb {
                    group[rb] = ra;
                }
            }
        }
    }
    let mut groups: std::collections::BTreeMap<usize, Vec<usize>> = std::collections::BTreeMap::new();
    for i in 0..n {
        let r = find(&mut group, i);
        groups.entry(r).or_default().push(i);
    }
    for (_, members) in groups {
        let first = &segs[members[0]];
        let k = wires[first.w].k;
        let cnt = members.len();
        let uv = dvec(first.u);
        // current spans (after ports)
        let span = |s: &Seg, ws: &[W]| {
            let w = &ws[s.w];
            let (_, _, lo, hi) = seg_span(w.pts[s.j], w.pts[s.j + 1]);
            (lo, hi)
        };
        // nesting order, inner first
        let mut left: Vec<usize> = members.clone();
        let mut ordered: Vec<usize> = Vec::new();
        while !left.is_empty() {
            let mut cands: Vec<usize> = Vec::new();
            for &x in &left {
                let (xl, xh) = span(&segs[x], wires);
                let contains_other = left.iter().any(|&y| {
                    if y == x {
                        return false;
                    }
                    let (yl, yh) = span(&segs[y], wires);
                    yl > xl + 1e-6 && yh < xh - 1e-6
                });
                if !contains_other {
                    cands.push(x);
                }
            }
            if cands.is_empty() {
                cands = left.clone();
            }
            // ties: the wire most offset towards where it turns goes first
            let key = |x: usize| {
                let s = &segs[x];
                let w = &wires[s.w];
                let v = dvec(seg_dir(w.pts[s.j], w.pts[s.j + 1]));
                let p = w.pts[s.j];
                (w.bundle, -(p.0 * v.0 + p.1 * v.1))
            };
            cands.sort_by(|&a, &b| {
                let (ba, oa) = key(a);
                let (bb, ob) = key(b);
                ba.cmp(&bb).then(oa.partial_cmp(&ob).unwrap_or(std::cmp::Ordering::Equal))
            });
            let pick = cands[0];
            ordered.push(pick);
            left.retain(|&x| x != pick);
        }
        if first.is_u {
            let depth = {
                let w = &wires[first.w];
                channel_depth(&envs[w.bundle], w.pts[first.j], w.pts[first.j + 1], first.u)
            };
            let pitch = if cnt <= 1 { 0.0 } else { k.min(depth / (cnt as f64 - 1.0)) };
            let base = first.pos * (if first.horiz { uv.1 } else { uv.0 });
            for (rank, &x) in ordered.iter().enumerate() {
                let s = &segs[x];
                let o = rank as f64 * pitch;
                set_pos(&mut wires[s.w].pts, s.j, uv, base + o);
                wires[s.w].offs[s.j] = o;
            }
        } else {
            let (lo, hi) = first.chan;
            let width = hi - lo;
            let pitch = if cnt <= 1 { 0.0 } else { k.min(width / (cnt as f64 - 1.0)) };
            let mid = (lo + hi) / 2.0;
            for (rank, &x) in ordered.iter().enumerate() {
                let s = &segs[x];
                let o = (rank as f64 - (cnt as f64 - 1.0) / 2.0) * pitch;
                set_pos(&mut wires[s.w].pts, s.j, uv, mid + o);
                wires[s.w].offs[s.j] = o;
            }
        }
    }
}

