pub fn free_interval(solids: &[Rect], pts: &[(f64, f64)], j: usize) -> (f64, f64) {
    let p = pts[j];
    let q = pts[j + 1];
    let vertical = (p.0 - q.0).abs() < 1e-9;
    let pos = if vertical { p.0 } else { p.1 };
    let mut lo = f64::NEG_INFINITY;
    let mut hi = f64::INFINITY;
    for far in [pts[j - 1], pts[j + 2]] {
        let f = if vertical { far.0 } else { far.1 };
        if f < pos - 1e-9 && f > lo {
            lo = f;
        }
        if f > pos + 1e-9 && f < hi {
            hi = f;
        }
