// Free segments settle midway in their channel when it is closed on both
// sides where they start; otherwise they keep hugging what they go around.
pub fn centre_staircases(env: &Env, pts: &mut Vec<(f64, f64)>) {
    let solids = env.solids();
    let n = pts.len();
    if n < 4 {
