// Brute force: Debug-formatted structs / tuples / vecs of rects for the mask key.
use std::collections::hash_map::DefaultHasher;
use std::hash::Hasher;

fn fnv1a64(b: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &c in b {
        h ^= c as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}
fn check(b: &[u8], t: u32) -> bool {
    let h = fnv1a64(b);
    if ((h >> 32) ^ h) as u32 == t || h as u32 == t || (h >> 32) as u32 == t {
        return true;
    }
    for term in [false, true] {
        let mut s = DefaultHasher::new();
        s.write(b);
        if term {
            s.write_u8(0xff);
        }
        let h = s.finish();
        if ((h >> 32) ^ h) as u32 == t || h as u32 == t || (h >> 32) as u32 == t {
            return true;
        }
    }
    false
}

