# usage: t.py file [-f] [-s] [-m]: snippets separated by lines '----'; runs original (or mine with -m) and shows links section
import subprocess,sys,os,re,tempfile
fn=sys.argv[1]
full='-f' in sys.argv; scene='-s' in sys.argv
bin_='/tmp/bin-link/executable' if '-m' in sys.argv else '/workspace/executable'
diff='-d' in sys.argv
snips=open(fn).read().split('\n----\n')
def run(b,src):
    d=tempfile.mkdtemp(prefix='/tmp/link/rr.')
    open(d+'/r_in.lini','w').write(src)
    r=subprocess.run([b,'r_in.lini'],capture_output=True,cwd=d)
    return r.stdout.decode(), r.stderr.decode(), r.returncode
def show(o,e,c):
    out=[]
    if e: out.append(e.rstrip())
    if full: out.append(o); return out
    lines=o.split('\n')
    if lines and lines[0].startswith('<svg'):
        m=re.search(r'viewBox="([^"]*)"',lines[0]); out.append('viewBox '+(m.group(1) if m else ''))
    inl=False
    for l in lines:
        if 'lini-links' in l: inl=True
        if scene and not inl and ('transform=' in l or '<rect' in l or '<ellipse' in l): out.append(l)
        if inl and l.strip() not in ('</svg>',''): out.append(l)
        if not inl and l.strip().startswith('.') and ('link' in l or 'marker' in l or 'cut' in l): out.append(l.strip())
    out.append('[exit %d]'%c)
    return out
for s in snips:
    if not s.strip(): continue
    print('#####', s.strip().replace('\n',' ⏎ ')[:150])
    o,e,c=run(bin_,s)
    if diff:
        o2,e2,c2=run('/tmp/bin-link/executable',s)
        if (o,e,c)==(o2,e2,c2): print('SAME'); continue
        import difflib
        for l in difflib.unified_diff(show(o,e,c),show(o2,e2,c2),'orig','mine',lineterm='',n=1): print(l)
        continue
    print('\n'.join(show(o,e,c)))

