// Brute-force search for the mask id key format.
use std::collections::hash_map::DefaultHasher;
use std::hash::Hasher;

fn fnv1a64(b: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &c in b {
        h ^= c as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}
fn fnv164(b: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &c in b {
        h = h.wrapping_mul(0x100000001b3);
        h ^= c as u64;
    }
    h
}
fn fnv1a32(b: &[u8]) -> u32 {
    let mut h: u32 = 0x811c9dc5;
    for &c in b {
        h ^= c as u32;
        h = h.wrapping_mul(0x01000193);
    }
    h
}
fn sip(b: &[u8], term: bool) -> u64 {
    let mut h = DefaultHasher::new();
    h.write(b);
    if term {
        h.write_u8(0xff);
    }
    h.finish()
}
fn crc32(b: &[u8]) -> u32 {
    let mut c: u32 = 0xffffffff;
    for &x in b {
        c ^= x as u32;
        for _ in 0..8 {
            c = if c & 1 != 0 { (c >> 1) ^ 0xedb88320 } else { c >> 1 };
        }
    }
    !c
}

fn check(b: &[u8], targets: &[u32]) -> Option<&'static str> {
    let h = fnv1a64(b);
    let f = ((h >> 32) ^ h) as u32;
    if targets.contains(&f) {
        return Some("fnv1a64-fold");
    }
    if targets.contains(&(h as u32)) {
        return Some("fnv1a64-lo");
    }
    if targets.contains(&((h >> 32) as u32)) {
        return Some("fnv1a64-hi");
    }
    let h = fnv164(b);
    if targets.contains(&(((h >> 32) ^ h) as u32)) || targets.contains(&(h as u32)) || targets.contains(&((h >> 32) as u32)) {
        return Some("fnv1-64");
    }
    if targets.contains(&fnv1a32(b)) {
        return Some("fnv1a32");
    }
    if targets.contains(&crc32(b)) {
        return Some("crc32");
    }
    for term in [false, true] {
        let h = sip(b, term);
        if targets.contains(&(((h >> 32) ^ h) as u32)) || targets.contains(&(h as u32)) || targets.contains(&((h >> 32) as u32)) {
            return Some("sip");
        }
    }
    None
}

fn disp(v: f64) -> String {
    format!("{}", v)
}
fn dbg(v: f64) -> String {
    format!("{:?}", v)
}
fn f4(v: f64) -> String {
    let mut s = format!("{:.4}", v);
    if s.contains('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.ends_with('.') {
            s.pop();
        }
    }
    if s == "-0" {
        s = "0".into();
    }
    s
}
fn p4(v: f64) -> String {
    format!("{:.4}", v)
}
fn exp(v: f64) -> String {
    format!("{:e}", v)
}


fn p1(v: f64) -> String { format!("{:.1}", v) }
fn p2(v: f64) -> String { format!("{:.2}", v) }
fn p3(v: f64) -> String { format!("{:.3}", v) }
fn p5(v: f64) -> String { format!("{:.5}", v) }
fn p6(v: f64) -> String { format!("{:.6}", v) }
fn p8(v: f64) -> String { format!("{:.8}", v) }
fn p10(v: f64) -> String { format!("{:.10}", v) }
fn p12(v: f64) -> String { format!("{:.12}", v) }
fn f32d(v: f64) -> String { format!("{}", v as f32) }
fn f32g(v: f64) -> String { format!("{:?}", v as f32) }
fn ri(v: f64) -> String { format!("{}", (v * 1000.0).round() as i64) }
fn ri2(v: f64) -> String { format!("{}", (v * 100.0).round() as i64) }
fn main() {
    let targets: Vec<u32> = vec![0x05ddd672];
    // items: (name, values)
    let items: Vec<(&str, Vec<f64>)> = vec![
        ("bg", vec![-20.0, -2.0, 40.0, 4.0]),
        ("bgx", vec![-20.0, -2.0, 20.0, 2.0]),
        ("bgc", vec![0.0, 0.0, 40.0, 4.0]),
        ("cut", vec![-3.0, -6.5, 6.0, 13.0]),
        ("cutx", vec![-3.0, -6.5, 3.0, 6.5]),
        ("cutc", vec![0.0, 0.0, 6.0, 13.0]),
        ("cutch", vec![0.0, 0.0, 3.0, 6.5]),
        ("pts", vec![-18.0, 0.0, 18.0, 0.0]),
        ("lab", vec![0.0, 0.0]),
        ("labb", vec![0.0, 0.0, 0.0, 10.0]),
        ("tb", vec![0.0, -5.0, 0.0, 10.0]),
        ("sw", vec![2.0]),
        ("m", vec![2.0]),
        ("fs", vec![10.0]),
        ("one", vec![1.0]),
        ("sz", vec![40.0, 4.0]),
        ("csz", vec![6.0, 13.0]),
    ];
    let fmts: Vec<(&str, fn(f64) -> String)> = vec![("p1", p1), ("p2", p2), ("p3", p3), ("p5", p5), ("p6", p6), ("p8", p8), ("p10", p10), ("p12", p12), ("f32d", f32d), ("f32g", f32g), ("ri", ri), ("ri2", ri2)];
    let seps = [",", " ", ", ", ";", "|", ":", "", "x", "/", "_", "-", "\n", "\t"];
    let wraps: [(&str, &str); 4] = [("", ""), ("(", ")"), ("[", "]"), ("{", "}")];
    let mut n: u64 = 0;
    for (fname, f) in &fmts {
        for s1 in seps.iter() {
            for (w0, w1) in wraps.iter() {
                let toks: Vec<String> = items.iter().map(|(_, v)| format!("{}{}{}", w0, v.iter().map(|x| f(*x)).collect::<Vec<_>>().join(s1), w1)).collect();
                let ni = toks.len();
                for s2 in seps.iter() {
                    // 1, 2, 3 items
                    for a in 0..ni {
                        let s = toks[a].clone();
                        n += 1;
                        if let Some(h) = check(s.as_bytes(), &targets) {
                            println!("FOUND {} {} {:?} {:?} {:?}", h, fname, s1, s2, s);
                        }
                        for b in 0..ni {
                            if b == a {
                                continue;
                            }
                            let s = format!("{}{}{}", toks[a], s2, toks[b]);
                            n += 1;
                            if let Some(h) = check(s.as_bytes(), &targets) {
                                println!("FOUND {} {} {:?} {:?} {:?}", h, fname, s1, s2, s);
                            }
                            for c in 0..ni {
                                if c == a || c == b {
                                    continue;
                                }
                                let s = format!("{}{}{}{}{}", toks[a], s2, toks[b], s2, toks[c]);
                                n += 1;
                                if let Some(h) = check(s.as_bytes(), &targets) {
                                    println!("FOUND {} {} {:?} {:?} {:?}", h, fname, s1, s2, s);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    eprintln!("tried {}", n);
}

