788	fn wave_d(p0: (f64, f64), p1: (f64, f64)) -> String {
789	    let l = ((p1.0 - p0.0).powi(2) + (p1.1 - p0.1).powi(2)).sqrt();
790	    let u = unitv(p0, p1);
791	    let nrm = (-u.1, u.0);
792	    let amp = 1.4;
793	    let lam = 12.0;
794	    let ramp = 6.0;
795	    let n = ((l / 3.0).round() as usize).max(1);
796	    let h = l / n as f64;
797	    let ss = |t: f64| {
798	        let t = t.clamp(0.0, 1.0);
799	        3.0 * t * t - 2.0 * t * t * t
800	    };
801	    let dss = |t: f64| if t <= 0.0 || t >= 1.0 { 0.0 } else { 6.0 * t - 6.0 * t * t };
802	    let w = 2.0 * std::f64::consts::PI / lam;
803	    let mut samples = Vec::new();
804	    for i in 0..=n {
805	        let x = i as f64 * h;
806	        let e1 = ss(x / ramp);
807	        let e2 = ss((l - x) / ramp);
808	        let (e, de) = if e1 < e2 { (e1, dss(x / ramp) / ramp) } else { (e2, -dss((l - x) / ramp) / ramp) };
809	        let y = amp * e * (w * x).sin();
810	        let dy = amp * (de * (w * x).sin() + e * w * (w * x).cos());
811	        samples.push((x, y, dy));
812	    }
813	    let to = |x: f64, y: f64| (p0.0 + u.0 * x + nrm.0 * y, p0.1 + u.1 * x + nrm.1 * y);
814	    let mut d = format!("M {} {}", f4(p0.0), f4(p0.1));
815	    for i in 0..n {
816	        let (xa, ya, da) = samples[i];
817	        let (xb, yb, db) = samples[i + 1];
818	        let ch = ((xb - xa).powi(2) + (yb - ya).powi(2)).sqrt() / 3.0;
819	        let la = (1.0 + da * da).sqrt();
820	        let lb = (1.0 + db * db).sqrt();
821	        let c1 = to(xa + ch / la, ya + da / la * ch);
822	        let c2 = to(xb - ch / lb, yb - db / lb * ch);
823	        let e = to(xb, yb);
