#!/usr/bin/env python3
# Collect (my raw mask inputs, original mask id) pairs and test key arithmetic variants.
import subprocess,sys,os,re,tempfile,glob,struct
M=0xffffffffffffffff
def fnv(b):
    h=0xcbf29ce484222325
    for c in b:
        h^=c; h=(h*0x100000001b3)&M
    return h
def h8(s):
    h=fnv(s.encode()); return '%08x'%(((h>>32)^h)&0xffffffff)
def rd(v):
    # Rust {:?} for f64
    if v!=v: return 'NaN'
    if v==float('inf'): return 'inf'
    if v==float('-inf'): return '-inf'
    if v==0: return '-0.0' if str(v).startswith('-') else '0.0'
    r=repr(v)
    a=abs(v)
    if 'e' in r or 'E' in r:
        m,e=r.split('e'); e=int(e)
        if a>=1e16 or a<1e-4:
            if '.' not in m: m=m
            return m+'e'+str(e)
        # expand
        return '%r'%v
    if '.' not in r: r+='.0'
    return r
def run(b,src_path,cwd):
    env=dict(os.environ); env['LINI_DBG_MASK']='1'
    r=subprocess.run([b,os.path.basename(src_path)],capture_output=True,cwd=cwd,env=env)
    return r.stdout.decode(errors='replace'),r.stderr.decode(errors='replace')
def pairs_for(path):
    d=os.path.dirname(path) or '.'
    o1,_=run('/workspace/executable',path,d)
    o2,e2=run('/tmp/bin-link/executable',path,d)
    ids=re.findall(r'<mask id="lini-label-cut-([0-9a-f]{8})" maskUnits="userSpaceOnUse" x="([^"]*)" y="([^"]*)" width="([^"]*)" height="([^"]*)">(.*?)</mask>',o1)
    mine=re.findall(r'<mask id="lini-label-cut-([0-9a-f]{8})" maskUnits="userSpaceOnUse" x="([^"]*)" y="([^"]*)" width="([^"]*)" height="([^"]*)">(.*?)</mask>',o2)
    dumps=[l for l in e2.split('\n') if l.startswith('MASK ')]
    out=[]
    if len(ids)!=len(mine) or len(mine)!=len(dumps):
        return out,('count mismatch %d %d %d'%(len(ids),len(mine),len(dumps)))
    bad=0
    for (i1,*r1),(i2,*r2),dm in zip(ids,mine,dumps):
        if r1!=r2: bad+=1; continue
        out.append((dm,i1))
    return out,('geometry mismatch %d'%bad if bad else '')
def snippets(fn):
    srcs=open(fn).read().split('\n----\n')
    res=[]
    for s in srcs:
        if not s.strip(): continue
        d=tempfile.mkdtemp(prefix='/tmp/link/mk.')
        p=d+'/r_in.lini'; open(p,'w').write(s)
        res.append(p)
    return res
if __name__=='__main__':
    allp=[]
    for a in sys.argv[1:]:
        paths=snippets(a) if a.endswith('.txt') else [a]
        for p in paths:
            pr,msg=pairs_for(p)
            if msg: print('#',p,msg,file=sys.stderr)
            allp+=pr
    import pickle
    pickle.dump(allp,open('/tmp/link/mk_pairs.pkl','wb'))
    print(len(allp),'pairs')

