// Advance of one char in em units (1.0 = font size).
pub fn char_advance_em(family: Family, weight: u32, c: char) -> f64 {
    let f = font(family, weight);
    if let Some(g) = f.glyph_for(c) {
        return f.adv[g as usize] as f64 / f.upem;
    }
    let cp = c as u32;
    if is_wide(cp) {
        return 1.0;
