824	fn plan_ports(world: &World, bundles: &[Bundle], wires: &mut [W]) {
825	    use std::collections::BTreeMap;
826	    let mut sides: BTreeMap<(usize, usize), Vec<(usize, usize)>> = BTreeMap::new();
827	    for (wi, w) in wires.iter().enumerate() {
828	        sides.entry((w.from, w.sa.idx())).or_default().push((wi, 0));
829	        sides.entry((w.to, w.sb.idx())).or_default().push((wi, 1));
830	    }
831	    // straight wires keep one position on both sides: the busier side decides
832	    let mut straight_pos: std::collections::HashMap<usize, f64> = std::collections::HashMap::new();
833	    let mut entries: Vec<((usize, usize), Vec<(usize, usize)>)> = sides.into_iter().collect();
834	    // busier sides first so straight wires take their positions there; an
835	    // inner node's side goes before its container's
836	    let inner_side = |ends: &Vec<(usize, usize)>| ends.iter().any(|&(wi, e)| wires[wi].inner_end == Some(e));
837	    entries.sort_by(|a, b| inner_side(&b.1).cmp(&inner_side(&a.1)).then(b.1.len().cmp(&a.1.len())).then(a.0.cmp(&b.0)));
838	    for ((node, sidx), mut ends) in entries {
839	        let side = [Side::Top, Side::Right, Side::Bottom, Side::Left][sidx];
840	        let r = world.rects[node];
841	        let k = wires[ends[0].0].k;
842	        // fan members sharing this node and side travel as one trunk port
843	        let fan_key = |w: &W, e: usize| if e == 0 { w.fan_s } else { w.fan_e };
844	        ends.sort_by(|&(wa, ea), &(wb, eb)| {
845	            let (ca, da) = end_shape(&wires[wa], ea);
846	            let (cb, db) = end_shape(&wires[wb], eb);
847	            let ka = if ca == -1 { da } else if ca == 1 { -da } else { 0.0 };
848	            let kb = if cb == -1 { db } else if cb == 1 { -db } else { 0.0 };
849	            // a wire turning into an inner track turns first
850	            let ua = u_key(&wires[wa], ea);
851	            let ub = u_key(&wires[wb], eb);
