// Width in font units summed over the string, then scaled.
pub fn text_width(family: Family, weight: u32, size: f64, s: &str) -> f64 {
    let f = font(family, weight);
    let mut units: f64 = 0.0;
    for c in s.chars() {
        if let Some(g) = f.glyph_for(c) {
            units += f.adv[g as usize] as f64;
        } else {
            let cp = c as u32;
            let em = if is_wide(cp) {
                1.0
            } else if family == Family::Sans && cp == 0x2300 {
                0.83
            } else {
                0.6
            };
            units += em * f.upem;
        }
    }
    units * size / f.upem
}
